package com.vitalshud;

import java.awt.Color;
import net.runelite.api.Prayer;

/**
 * Labels and colours for the active prayer row.
 *
 * <p>Both are derived from the prayer's name rather than a hand-written table,
 * so prayers added to the game later show up with a sensible chip instead of
 * needing a code change.
 */
final class ActivePrayers
{
	private static final Color PROTECTION = new Color(96, 156, 220);
	private static final Color MELEE = new Color(206, 92, 78);
	private static final Color RANGED = new Color(104, 190, 104);
	private static final Color MAGIC = new Color(150, 122, 220);
	private static final Color RECOIL = new Color(214, 154, 76);
	private static final Color OTHER = new Color(160, 160, 160);

	/**
	 * Up to three letters: the initials of a multi-word prayer, or the opening of
	 * a single-word one.
	 */
	static String label(Prayer prayer)
	{
		String name = prayer.name();

		// Ruinous powers are prefixed in the API; the prefix says nothing useful
		// on a chip that is only three letters wide.
		if (name.startsWith("RP_"))
		{
			name = name.substring(3);
		}

		String[] words = name.split("_");
		if (words.length == 1)
		{
			return capitalise(words[0], 3);
		}

		StringBuilder initials = new StringBuilder(3);
		for (String word : words)
		{
			if (initials.length() == 3 || word.isEmpty())
			{
				break;
			}

			// "Of" and "From" are filler in prayer names and waste a slot.
			if (word.equals("OF") || word.equals("FROM"))
			{
				continue;
			}

			initials.append(word.charAt(0));
		}

		return initials.toString();
	}

	/**
	 * Whether the game already draws this prayer as an icon over your head.
	 *
	 * <p>Matched on the name rather than listed, so the ruinous equivalents and
	 * anything added later are covered without a code change.
	 */
	static boolean isOverhead(Prayer prayer)
	{
		String name = prayer.name();

		// Protect Item is deliberately absent: it protects an item on death but
		// puts nothing over your head, so hiding it would lose the only place you
		// could see it.
		return name.contains("PROTECT_FROM")
			|| name.contains("DAMPEN")
			|| name.contains("RETRIBUTION")
			|| name.contains("REDEMPTION")
			|| name.contains("SMITE")
			|| name.contains("WRATH")
			|| name.contains("REBUKE");
	}

	static Color color(Prayer prayer)
	{
		String name = prayer.name();

		if (name.contains("PROTECT"))
		{
			return PROTECTION;
		}

		if (name.contains("RETRIBUTION") || name.contains("REDEMPTION") || name.contains("SMITE")
			|| name.contains("WRATH"))
		{
			return RECOIL;
		}

		if (name.contains("STRENGTH") || name.contains("PIETY") || name.contains("CHIVALRY")
			|| name.contains("REFLEXES") || name.contains("SKIN") || name.contains("CLARITY"))
		{
			return MELEE;
		}

		if (name.contains("EYE") || name.contains("RIGOUR") || name.contains("SIGHT"))
		{
			return RANGED;
		}

		if (name.contains("MYSTIC") || name.contains("AUGURY") || name.contains("MAGIC")
			|| name.contains("WILL") || name.contains("LORE"))
		{
			return MAGIC;
		}

		return OTHER;
	}

	private static String capitalise(String word, int length)
	{
		String trimmed = word.length() <= length ? word : word.substring(0, length);
		return trimmed.charAt(0) + trimmed.substring(1).toLowerCase();
	}

	private ActivePrayers()
	{
	}
}

package com.vitalshud;

/**
 * How far a low-vital alert spreads. One segment only lights the vital that
 * dropped; the whole outline lights everything so it is visible without having
 * to pick out a particular segment.
 */
public enum AlertMode
{
	OFF("Off"),
	BAR("The segment that dropped"),
	HUD("The whole outline");

	private final String name;

	AlertMode(String name)
	{
		this.name = name;
	}

	@Override
	public String toString()
	{
		return name;
	}
}

package com.vitalshud;

import net.runelite.api.Skill;
import net.runelite.api.gameval.SpriteID;

/**
 * A combat skill whose current level is worth watching, and the game's own icon
 * for it.
 *
 * <p>Reading the level directly rather than tracking what raised it means every
 * source is covered at once - potions, an imbued heart, a Dwarven rock cake
 * draining you - without a table of effects to keep up to date.
 */
enum BoostedSkill
{
	ATTACK(Skill.ATTACK, SpriteID.Staticons.ATTACK),
	STRENGTH(Skill.STRENGTH, SpriteID.Staticons.STRENGTH),
	DEFENCE(Skill.DEFENCE, SpriteID.Staticons.DEFENCE),
	RANGED(Skill.RANGED, SpriteID.Staticons.RANGED),
	MAGIC(Skill.MAGIC, SpriteID.Staticons.MAGIC);

	private final Skill skill;
	private final int sprite;

	BoostedSkill(Skill skill, int sprite)
	{
		this.skill = skill;
		this.sprite = sprite;
	}

	Skill skill()
	{
		return skill;
	}

	int sprite()
	{
		return sprite;
	}
}

package com.vitalshud;

/**
 * Which side of the character a vital's bracket takes.
 */
public enum BracketSide
{
	LEFT("Left"),
	RIGHT("Right"),
	BOTTOM("Bottom"),
	TOP("Top");

	private final String name;

	BracketSide(String name)
	{
		this.name = name;
	}

	/**
	 * Whether the bracket's long side runs vertically.
	 */
	public boolean isUpright()
	{
		return this == LEFT || this == RIGHT;
	}

	@Override
	public String toString()
	{
		return name;
	}
}

package com.vitalshud;

import java.awt.Polygon;
import java.awt.geom.Rectangle2D;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;

/**
 * Works out the box a character's body occupies on screen.
 *
 * <p>Built from two things read off the client - how many pixels a world unit
 * covers, and how far the camera's tilt squashes a standing figure - rather
 * than from the model's outline. The outline is the obvious source and the
 * wrong one: it is the silhouette of everything the character carries, so a
 * scythe is as much a part of it as an arm, and no box loose enough to keep a
 * cape is tight enough to throw the scythe out.
 *
 * <p>Measuring instead of tracing makes equipment structurally incapable of
 * changing the result, while still following zoom, distance and camera angle,
 * because both measurements come from the client every frame.
 *
 * <p>Kept apart from the drawing because it is the one part of this plugin with
 * arithmetic worth checking without a client attached.
 */
class CharacterMeasure
{
	/**
	 * World height a character is measured as. A fixed value rather than the
	 * model's logical height, so a halberd, a tall hat or an animation cannot
	 * change how big the brackets come out.
	 */
	static final int PLAYER_HEIGHT = 200;

	/**
	 * Side of one tile in world units, which is the ruler the player's own tile
	 * polygon provides.
	 */
	private static final double TILE_SIZE = 128d;

	/**
	 * Half-length of the rulers laid on the ground when the tile itself cannot be
	 * measured.
	 */
	private static final int RULER = 64;

	/**
	 * Directions the ruler is laid in, as local offsets. A ruler pointing across
	 * the camera keeps its full length on screen while one pointing away from it
	 * is squashed by the camera's pitch, so the longest of several directions is
	 * the one that measures true.
	 */
	private static final int[][] RULER_DIRECTIONS = {{1, 0}, {0, 1}, {1, 1}, {1, -1}};

	/**
	 * Frame width as a share of the character's height.
	 */
	private static final double ASPECT = 0.45d;

	/**
	 * Bounds on the measured camera squash, guarding against a reading taken from
	 * a projection that came back nonsense.
	 */
	private static final double MIN_SQUASH = 0.15d;
	private static final double MAX_SQUASH = 1.2d;

	private final Client client;

	/**
	 * Last usable reading of how big a world unit is on screen, kept so a frame
	 * where nothing can be projected does not resize the brackets.
	 */
	private double lastPixelsPerUnit;

	/**
	 * Last usable reading of how far the camera's tilt squashes a standing
	 * character, kept for the frames where it cannot be measured.
	 */
	private double lastSquash = 1d;

	CharacterMeasure(Client client)
	{
		this.client = client;
	}

	/**
	 * The box the character's body occupies on screen, or null if this frame
	 * cannot be measured at all.
	 */
	Rectangle2D bounds(Player local)
	{
		LocalPoint location = local.getLocalLocation();
		if (location == null)
		{
			return null;
		}

		int plane = client.getTopLevelWorldView().getPlane();
		Point feet = Perspective.localToCanvas(client, location, plane, 0);
		if (feet == null)
		{
			return null;
		}

		double pixelsPerUnit = pixelsPerUnit(local, location, plane);
		if (pixelsPerUnit <= 0d)
		{
			return null;
		}

		double squash = squash(location, plane, feet, pixelsPerUnit);

		return box(feet.getX(), feet.getY(), pixelsPerUnit, squash);
	}

	/**
	 * The box a character of the measured size stands in, given where their feet
	 * are. Split out from the reading so the arithmetic can be checked on its
	 * own.
	 */
	static Rectangle2D box(double feetX, double feetY, double pixelsPerUnit, double squash)
	{
		double height = PLAYER_HEIGHT * pixelsPerUnit * squash;
		double width = PLAYER_HEIGHT * ASPECT * pixelsPerUnit;

		return new Rectangle2D.Double(feetX - width / 2d, feetY - height, width, height);
	}

	/**
	 * How many pixels one world unit covers at the character's position.
	 *
	 * @return pixels per world unit, or 0 if nothing has ever been measured
	 */
	private double pixelsPerUnit(Player local, LocalPoint location, int plane)
	{
		// The player's own tile is a ready-made ruler of known size, and the client
		// hands it over already projected.
		double best = measureTile(local.getCanvasTilePoly());

		if (best <= 0d)
		{
			best = measureGround(location, plane);
		}

		// Zoomed right in the tile runs off screen and cannot be projected. Its
		// size barely moves between frames, so the last good reading stands in
		// rather than letting the frame collapse.
		if (best > 0d)
		{
			lastPixelsPerUnit = best;
			return best;
		}

		return lastPixelsPerUnit;
	}

	/**
	 * How far the camera's tilt squashes a standing character, as a share of
	 * their full height. One looking level at them, less as the camera swings
	 * overhead.
	 *
	 * <p>Read off the client by projecting a point level with their head, rather
	 * than worked out from the camera angle. That projection fails when zoomed
	 * right in and the point leaves the viewport, but the reading barely moves
	 * between frames, so the last good one stands in.
	 */
	private double squash(LocalPoint location, int plane, Point feet, double pixelsPerUnit)
	{
		Point head = Perspective.localToCanvas(client, location, plane, PLAYER_HEIGHT);

		if (head != null && pixelsPerUnit > 0d)
		{
			double measured = (feet.getY() - head.getY()) / (PLAYER_HEIGHT * pixelsPerUnit);

			if (usableSquash(measured))
			{
				lastSquash = measured;
			}
		}

		return lastSquash;
	}

	/**
	 * Whether a squash reading is close enough to sane to keep.
	 */
	static boolean usableSquash(double measured)
	{
		return measured > MIN_SQUASH && measured < MAX_SQUASH;
	}

	/**
	 * Pixels per world unit taken from a tile polygon: the longest of its sides
	 * and diagonals, each against the distance it covers on the ground.
	 */
	static double measureTile(Polygon tile)
	{
		if (tile == null || tile.npoints < 4)
		{
			return 0d;
		}

		double best = 0d;

		for (int i = 0; i < 4; i++)
		{
			best = Math.max(best, span(tile, i, (i + 1) % 4) / TILE_SIZE);
		}

		double diagonal = TILE_SIZE * Math.sqrt(2d);
		best = Math.max(best, span(tile, 0, 2) / diagonal);
		best = Math.max(best, span(tile, 1, 3) / diagonal);

		return best;
	}

	private static double span(Polygon tile, int from, int to)
	{
		return Math.hypot(tile.xpoints[to] - tile.xpoints[from], tile.ypoints[to] - tile.ypoints[from]);
	}

	/**
	 * Fallback ruler laid on the ground either side of the character, for when
	 * the tile polygon is unavailable.
	 */
	private double measureGround(LocalPoint location, int plane)
	{
		double best = 0d;

		for (int[] direction : RULER_DIRECTIONS)
		{
			// Diagonals cover more ground than the axes, so their length is taken
			// out again afterwards rather than reading as a bigger world.
			double length = Math.sqrt(direction[0] * direction[0] + direction[1] * direction[1]);

			int dx = (int) Math.round(direction[0] * RULER / length);
			int dy = (int) Math.round(direction[1] * RULER / length);

			Point from = Perspective.localToCanvas(client,
				new LocalPoint(location.getX() - dx, location.getY() - dy,
					client.getTopLevelWorldView()), plane, 0);
			Point to = Perspective.localToCanvas(client,
				new LocalPoint(location.getX() + dx, location.getY() + dy,
					client.getTopLevelWorldView()), plane, 0);

			if (from == null || to == null)
			{
				continue;
			}

			double pixels = Math.hypot(to.getX() - from.getX(), to.getY() - from.getY());
			best = Math.max(best, pixels / (RULER * 2d));
		}

		return best;
	}
}

package com.vitalshud;

/**
 * Which flank hitpoints or prayer takes.
 *
 * <p>Only the two uprights are offered, so neither can be put somewhere it would
 * collide with the vitals that own the top and bottom.
 */
public enum HorizontalSide
{
	LEFT("Left", BracketSide.LEFT),
	RIGHT("Right", BracketSide.RIGHT);

	private final String name;
	private final BracketSide side;

	HorizontalSide(String name, BracketSide side)
	{
		this.name = name;
		this.side = side;
	}

	public BracketSide bracketSide()
	{
		return side;
	}

	public HorizontalSide opposite()
	{
		return this == LEFT ? RIGHT : LEFT;
	}

	@Override
	public String toString()
	{
		return name;
	}
}

package com.vitalshud;

/**
 * What an active prayer keeps on screen once the out-of-combat hide would
 * otherwise have taken the outline away, so prayer drain doesn't go unnoticed.
 */
public enum IdleHold
{
	NOTHING("Nothing"),
	PRAYER_BAR("The prayer segment"),
	WHOLE_HUD("The whole outline");

	private final String name;

	IdleHold(String name)
	{
		this.name = name;
	}

	@Override
	public String toString()
	{
		return name;
	}
}

package com.vitalshud;

/**
 * The level a segment is currently drawn at, which trails the real value so the
 * outline drains rather than snapping. One of these is kept per vital.
 */
final class MeterState
{
	/**
	 * A drop and a recovery are eased over their configured time. Three time
	 * constants lands within a couple of percent of the target, so treating the
	 * configured duration as three tau makes the setting mean what it says.
	 */
	private static final float TAU_DIVISOR = 3f;

	private float displayed = -1f;
	private long lastFrame;

	/**
	 * Moves the drawn level towards the real one and returns where it now sits.
	 *
	 * @param target  real level, 0..1
	 * @param animate false to snap straight to the target
	 * @param dropMs  time a fall should take
	 * @param riseMs  time a rise should take
	 */
	float advance(float target, boolean animate, int dropMs, int riseMs)
	{
		long now = System.currentTimeMillis();

		// First frame, or the plugin was off for a while - start where the value
		// actually is rather than sweeping up from empty.
		if (displayed < 0f || !animate)
		{
			displayed = target;
			lastFrame = now;
			return displayed;
		}

		long elapsed = now - lastFrame;
		lastFrame = now;

		// A long gap means the client was paused or the outline was hidden;
		// sweeping across it would look like a phantom hit.
		if (elapsed <= 0 || elapsed > 1000)
		{
			displayed = target;
			return displayed;
		}

		float duration = Math.max(1f, (target < displayed ? dropMs : riseMs) / TAU_DIVISOR);
		float step = 1f - (float) Math.exp(-elapsed / duration);

		displayed += (target - displayed) * step;

		// Settle exactly rather than creeping, so a full segment reads as full.
		if (Math.abs(target - displayed) < 0.001f)
		{
			displayed = target;
		}

		return displayed;
	}

	void reset()
	{
		displayed = -1f;
	}
}

package com.vitalshud;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Shape;
import java.awt.geom.Path2D;
import java.awt.geom.PathIterator;
import java.awt.geom.Rectangle2D;

/**
 * Builds and paints the brackets that frame the player.
 *
 * <p>Each vital gets its own bracket rather than a share of one closed shape.
 * That keeps every bracket the same size and shape as its neighbours, which a
 * split silhouette never manages - a model is lopsided by nature, since it
 * carries a weapon on one side and a cape behind.
 *
 * <p>A bracket drains by tracing part of its own path, so the fill follows the
 * corners rather than being clipped by them.
 */
final class OutlineRenderer
{
	/**
	 * How finely curves are broken into lines when measuring and trimming a
	 * bracket. Half a pixel is well under what the stroke can show.
	 */
	private static final double FLATNESS = 0.5d;

	/**
	 * One bracket: a long side with a short return turned inwards at each end.
	 *
	 * <p>The path is built starting from the end the bracket should fill from, so
	 * trimming it to a fraction drains it in the right direction - upwards on the
	 * uprights, left to right on the flat ones.
	 */
	static Shape bracket(Rectangle2D frame, BracketSide side, double foot, double radius)
	{
		double left = frame.getMinX();
		double right = frame.getMaxX();
		double top = frame.getMinY();
		double bottom = frame.getMaxY();

		// A corner cannot be rounder than the return it turns into, nor than half
		// the side it turns off.
		double along = side.isUpright() ? frame.getHeight() : frame.getWidth();
		double r = Math.max(0d, Math.min(radius, Math.min(foot, along / 2d)));

		Path2D.Double path = new Path2D.Double();

		switch (side)
		{
			case LEFT:
				path.moveTo(left + foot, bottom);
				path.lineTo(left + r, bottom);
				path.quadTo(left, bottom, left, bottom - r);
				path.lineTo(left, top + r);
				path.quadTo(left, top, left + r, top);
				path.lineTo(left + foot, top);
				break;

			case RIGHT:
				path.moveTo(right - foot, bottom);
				path.lineTo(right - r, bottom);
				path.quadTo(right, bottom, right, bottom - r);
				path.lineTo(right, top + r);
				path.quadTo(right, top, right - r, top);
				path.lineTo(right - foot, top);
				break;

			case BOTTOM:
				path.moveTo(left, bottom - foot);
				path.lineTo(left, bottom - r);
				path.quadTo(left, bottom, left + r, bottom);
				path.lineTo(right - r, bottom);
				path.quadTo(right, bottom, right, bottom - r);
				path.lineTo(right, bottom - foot);
				break;

			default:
				path.moveTo(left, top + foot);
				path.lineTo(left, top + r);
				path.quadTo(left, top, left + r, top);
				path.lineTo(right - r, top);
				path.quadTo(right, top, right, top + r);
				path.lineTo(right, top + foot);
				break;
		}

		return path;
	}

	/**
	 * The stretch of a path between two fractions of its length, or null when
	 * that stretch is empty.
	 */
	static Shape subPath(Shape path, double from, double to)
	{
		double total = length(path);
		if (total <= 0d)
		{
			return null;
		}

		double start = total * clamp(Math.min(from, to));
		double end = total * clamp(Math.max(from, to));

		if (end - start < 0.01d)
		{
			return null;
		}

		Path2D.Double trimmed = new Path2D.Double();
		double[] coords = new double[6];
		double travelled = 0d;
		double previousX = 0d;
		double previousY = 0d;
		boolean begun = false;

		for (PathIterator it = path.getPathIterator(null, FLATNESS); !it.isDone(); it.next())
		{
			int type = it.currentSegment(coords);

			if (type == PathIterator.SEG_MOVETO)
			{
				previousX = coords[0];
				previousY = coords[1];
				continue;
			}

			if (type != PathIterator.SEG_LINETO)
			{
				continue;
			}

			double dx = coords[0] - previousX;
			double dy = coords[1] - previousY;
			double segment = Math.sqrt(dx * dx + dy * dy);

			if (segment > 0d)
			{
				// Where this segment overlaps the stretch being kept.
				double overlapFrom = Math.max(start, travelled);
				double overlapTo = Math.min(end, travelled + segment);

				if (overlapTo > overlapFrom)
				{
					double t0 = (overlapFrom - travelled) / segment;
					double t1 = (overlapTo - travelled) / segment;

					if (!begun)
					{
						trimmed.moveTo(previousX + dx * t0, previousY + dy * t0);
						begun = true;
					}

					trimmed.lineTo(previousX + dx * t1, previousY + dy * t1);
				}
			}

			travelled += segment;
			previousX = coords[0];
			previousY = coords[1];
		}

		return begun ? trimmed : null;
	}

	static double length(Shape path)
	{
		double[] coords = new double[6];
		double total = 0d;
		double previousX = 0d;
		double previousY = 0d;

		for (PathIterator it = path.getPathIterator(null, FLATNESS); !it.isDone(); it.next())
		{
			int type = it.currentSegment(coords);

			if (type == PathIterator.SEG_LINETO)
			{
				double dx = coords[0] - previousX;
				double dy = coords[1] - previousY;
				total += Math.sqrt(dx * dx + dy * dy);
			}

			if (type == PathIterator.SEG_MOVETO || type == PathIterator.SEG_LINETO)
			{
				previousX = coords[0];
				previousY = coords[1];
			}
		}

		return total;
	}

	/**
	 * Lays a bracket down in passes: a soft glow, a dark rim for contrast, the
	 * colour itself, then a bright core. The rim is what keeps it legible over
	 * pale ground, which a single stroke never manages.
	 */
	static void stroke(Graphics2D g, Shape path, float thickness, int glow, Color color)
	{
		if (path == null)
		{
			return;
		}

		for (int pass = glow; pass > 0; pass--)
		{
			g.setStroke(stroke(thickness + pass * 2.2f));
			g.setColor(withAlpha(color, 34 - pass * 4));
			g.draw(path);
		}

		g.setStroke(stroke(thickness + 2.2f));
		g.setColor(new Color(0, 0, 0, 130));
		g.draw(path);

		g.setStroke(stroke(thickness));
		g.setColor(color);
		g.draw(path);

		// A thinner, brighter pass down the middle gives the stroke a lit edge
		// instead of reading as a flat band of colour.
		g.setStroke(stroke(Math.max(1f, thickness * 0.42f)));
		g.setColor(withAlpha(blend(color, Color.WHITE, 0.55f), 190));
		g.draw(path);
	}

	private static BasicStroke stroke(float width)
	{
		return new BasicStroke(Math.max(0.5f, width), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
	}

	private static double clamp(double value)
	{
		return Math.max(0d, Math.min(1d, value));
	}

	static Color blend(Color from, Color to, float amount)
	{
		float t = Math.max(0f, Math.min(1f, amount));

		return new Color(
			Math.round(from.getRed() + (to.getRed() - from.getRed()) * t),
			Math.round(from.getGreen() + (to.getGreen() - from.getGreen()) * t),
			Math.round(from.getBlue() + (to.getBlue() - from.getBlue()) * t),
			from.getAlpha());
	}

	static Color withAlpha(Color color, int alpha)
	{
		int scaled = Math.max(0, Math.min(255, alpha * color.getAlpha() / 255));
		return new Color(color.getRed(), color.getGreen(), color.getBlue(), scaled);
	}

	private OutlineRenderer()
	{
	}
}

