import java.util.HashMap;
import java.util.Map;

/**
 * What a consumable would restore, used to draw the preview segment.
 *
 * <p>Keyed by item name rather than item id on purpose: doses, blighted copies
 * and barbarian mixes all normalise onto the same entry, so one row covers
 * "Prayer potion(1)" through "Blighted super restore(4)" without listing ids.
 * The trade-off is that a client running in another language will not match, and
 * the preview simply does not appear.
 */
final class RestoreValues
{
	/**
	 * Extra prayer a holy wrench grants, as a share of the prayer level. Applies
	 * to prayer potions, super restores and sanfew serums.
	 */
	private static final float WRENCH_BONUS = 0.02f;

	/**
	 * A restore expressed as a flat amount plus a fraction of the relevant level,
	 * which is how the game's own potions are defined.
	 */
	static final class Restore
	{
		final VitalType type;
		final int flat;
		final float percentOfLevel;
		final boolean overheals;

		/**
		 * Whether a holy wrench adds to this restore. Only the prayer potions
		 * benefit; ancient brews and the like do not.
		 */
		final boolean wrenchApplies;

		private Restore(VitalType type, int flat, float percentOfLevel, boolean overheals,
			boolean wrenchApplies)
		{
			this.type = type;
			this.flat = flat;
			this.percentOfLevel = percentOfLevel;
			this.overheals = overheals;
			this.wrenchApplies = wrenchApplies;
		}

		int amount(int level, boolean holyWrench)
		{
			float share = percentOfLevel + (holyWrench && wrenchApplies ? WRENCH_BONUS : 0f);
			return flat + (int) Math.floor(share * level);
		}
	}

	private static final Map<String, Restore> RESTORES = new HashMap<>();

	private static void food(int heal, String... names)
	{
		for (String name : names)
		{
			RESTORES.put(name, new Restore(VitalType.HITPOINTS, heal, 0f, false, false));
		}
	}

	private static void potion(VitalType type, int flat, float percent, boolean overheals,
		boolean wrench, String... names)
	{
		for (String name : names)
		{
			RESTORES.put(name, new Restore(type, flat, percent, overheals, wrench));
		}
	}

	static
	{
		food(1, "anchovies", "seaweed");
		food(2, "banana", "strange fruit", "purple sweets", "chocolate bar", "spinach roll");
		food(3, "shrimps", "cooked chicken", "cooked meat", "roll", "crayfish");
		food(4, "sardine", "cake", "chocolate slice", "baked potato", "slice of cake",
			"toad's legs", "equa leaves");
		food(5, "herring", "chocolate cake", "bread", "guthix rest", "cup of tea",
			"cooked rabbit", "roast rabbit");
		food(6, "meat pie", "summer pie", "roast bird meat", "mackerel", "choc-ice");
		food(7, "trout", "cod", "apple pie", "plain pizza", "meat pizza", "roast beast meat");
		food(8, "pike", "peach", "papaya fruit", "cooked crab meat");
		food(9, "salmon", "anchovy pizza", "fishcake");
		food(10, "tuna", "rainbow fish", "cooked chompy");
		food(11, "wild pie", "jug of wine", "pineapple pizza", "stew", "lobster soup");
		food(12, "lobster", "cave eel", "roast beast");
		food(13, "bass", "potato with butter");
		food(14, "swordfish", "chilli potato", "fish pie");
		food(16, "monkfish", "potato with cheese", "egg potato", "admiral pie");
		food(18, "cooked karambwan");
		food(19, "curry", "ugthanki kebab", "wine of zamorak");
		food(20, "shark", "mushroom potato", "dragonfruit pie");
		food(21, "sea turtle", "mycil pie");
		food(22, "manta ray", "dark crab", "tuna potato");

		// Anglerfish scales with hitpoints level and is allowed to go over the cap.
		// Treated as its high-level value, which is what it is used at in practice.
		potion(VitalType.HITPOINTS, 22, 0f, true, false, "anglerfish");

		// Brews heal a share of your maximum and are allowed to exceed it.
		potion(VitalType.HITPOINTS, 2, 0.15f, true, false, "saradomin brew", "xeric's aid");

		potion(VitalType.PRAYER, 7, 0.25f, false, true,
			"prayer potion", "prayer mix", "blessed prayer potion");
		potion(VitalType.PRAYER, 8, 0.27f, false, true,
			"super restore", "super restore mix", "blessed super restore");
		potion(VitalType.PRAYER, 4, 0.30f, false, true, "sanfew serum", "sanfew salve");
		potion(VitalType.PRAYER, 2, 0.10f, false, false, "ancient brew", "forgotten brew");
		potion(VitalType.PRAYER, 5, 0.25f, false, true, "moonlight potion");

		potion(VitalType.RUN, 20, 0f, false, false, "stamina potion", "stamina mix");
		potion(VitalType.RUN, 10, 0f, false, false, "energy potion", "energy mix");
		potion(VitalType.RUN, 20, 0f, false, false, "super energy potion", "super energy mix");
		potion(VitalType.RUN, 50, 0f, false, false, "extreme energy potion");
	}

	/**
	 * The restore for an item, or null if it is not a consumable we know about.
	 */
	static Restore forItem(String itemName)
	{
		if (itemName == null)
		{
			return null;
		}

		return RESTORES.get(normalise(itemName));
	}

	/**
	 * Reduces an item name to its table key: lower case, no dose or variant
	 * suffix in brackets, and no "blighted" prefix.
	 */
	static String normalise(String itemName)
	{
		String name = itemName.toLowerCase().trim();

		int bracket = name.indexOf('(');
		if (bracket > 0)
		{
			name = name.substring(0, bracket).trim();
		}

		if (name.startsWith("blighted "))
		{
			name = name.substring("blighted ".length());
		}

		return name;
	}

	private RestoreValues()
	{
	}
}

