import java.util.HashMap;
import java.util.Map;

/**
 * What a weapon's special attack costs, as a percentage of the special bar.
 *
 * <p>The client publishes how much energy you have but not what the weapon in
 * your hand would spend, and no varbit or script carries it either, so it has to
 * be listed. Keyed by name so that ornament kits, imbues and locked variants all
 * fall onto one entry.
 *
 * <p>The table is hand-kept and will not know every weapon. An unknown one is
 * reported as zero, which leaves the plugin to fall back on a fixed percentage
 * rather than guessing.
 */
final class SpecialAttacks
{
	private static final Map<String, Integer> COSTS = new HashMap<>();

	private static void cost(int percent, String... weapons)
	{
		for (String weapon : weapons)
		{
			COSTS.put(weapon, percent);
		}
	}

	static
	{
		cost(25, "dragon dagger", "dragon longsword", "dragon mace", "dragon spear",
			"zamorakian spear", "zamorakian hasta", "dragon knife", "dragon thrownaxe",
			"osmumten's fang");

		cost(30, "dragon halberd", "crystal halberd");

		cost(35, "statius's warhammer");

		cost(40, "dragon sword", "armadyl crossbow");

		cost(50, "dragon warhammer", "dragon claws", "abyssal whip", "abyssal tentacle",
			"abyssal dagger", "abyssal bludgeon", "armadyl godsword", "saradomin godsword",
			"zamorak godsword", "ancient godsword", "granite maul", "toxic blowpipe",
			"elder maul", "barrelchest anchor", "dinh's bulwark", "voidwaker", "craw's bow",
			"webweaver bow", "viggora's chainmace", "ursine chainmace", "thammaron's sceptre",
			"accursed sceptre");

		cost(55, "dragon scimitar", "dark bow", "magic shortbow", "volatile nightmare staff");

		cost(60, "dragon 2h sword", "dragon crossbow", "granite hammer");

		cost(65, "saradomin's blessed sword");

		cost(75, "bone dagger", "dorgeshuun crossbow", "zaryte crossbow",
			"eldritch nightmare staff");

		cost(100, "bandos godsword", "saradomin sword", "leaf-bladed battleaxe",
			"excalibur", "enhanced excalibur", "ancient mace", "staff of the dead",
			"toxic staff of the dead", "seercull", "dragon axe", "infernal axe", "crystal axe",
			"dragon pickaxe", "infernal pickaxe", "crystal pickaxe", "dragon harpoon",
			"infernal harpoon", "crystal harpoon");
	}

	/**
	 * The weapon's special attack cost, or 0 when it is unknown or the weapon has
	 * no special attack at all.
	 */
	static int cost(String weaponName)
	{
		if (weaponName == null)
		{
			return 0;
		}

		Integer cost = COSTS.get(normalise(weaponName));
		return cost == null ? 0 : cost;
	}

	/**
	 * Reduces a weapon name to its table key: lower case, and without the
	 * bracketed suffix that ornament kits, imbues and locked copies carry.
	 */
	static String normalise(String weaponName)
	{
		String name = weaponName.toLowerCase().trim();

		int bracket = name.indexOf('(');
		if (bracket > 0)
		{
			name = name.substring(0, bracket).trim();
		}

		return name;
	}

	private SpecialAttacks()
	{
	}
}

package com.vitalshud;

import java.awt.Font;
import net.runelite.client.ui.FontManager;

/**
 * Typeface for the value text and labels.
 */
public enum TextFont
{
	RUNESCAPE_SMALL("RuneScape small"),
	RUNESCAPE("RuneScape"),
	RUNESCAPE_BOLD("RuneScape bold"),
	SANS_SERIF("Sans serif");

	private final String name;

	TextFont(String name)
	{
		this.name = name;
	}

	public Font font(int size)
	{
		switch (this)
		{
			case RUNESCAPE:
				return FontManager.getRunescapeFont().deriveFont((float) size);
			case RUNESCAPE_BOLD:
				return FontManager.getRunescapeBoldFont().deriveFont((float) size);
			case SANS_SERIF:
				return new Font(Font.SANS_SERIF, Font.BOLD, size);
			default:
				return FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD, (float) size);
		}
	}

	/**
	 * Whether this font wants antialiasing. The game's own faces are pixel fonts
	 * and smear when smoothed; an ordinary outline font needs it to look right.
	 */
	public boolean antialias()
	{
		return this == SANS_SERIF;
	}

	@Override
	public String toString()
	{
		return name;
	}
}

package com.vitalshud;

public enum ValueReadout
{
	NONE("Nothing"),
	CURRENT("Current"),
	CURRENT_MAX("Current / max"),
	PERCENT("Percentage"),
	BOTH("Current / max and percentage");

	private final String name;

	ValueReadout(String name)
	{
		this.name = name;
	}

	public String format(int current, int max)
	{
		switch (this)
		{
			case CURRENT:
				return String.valueOf(current);
			case CURRENT_MAX:
				return current + "/" + max;
			case PERCENT:
				return percent(current, max) + "%";
			case BOTH:
				return current + "/" + max + "  " + percent(current, max) + "%";
			default:
				return null;
		}
	}

	private static int percent(int current, int max)
	{
		return max <= 0 ? 0 : Math.round(100f * current / max);
	}

	@Override
	public String toString()
	{
		return name;
	}
}

package com.vitalshud;

/**
 * Which end special attack or run energy takes.
 *
 * <p>Only the two flat sides are offered, leaving the uprights to hitpoints and
 * prayer.
 */
public enum VerticalSide
{
	TOP("Top", BracketSide.TOP),
	BOTTOM("Bottom", BracketSide.BOTTOM);

	private final String name;
	private final BracketSide side;

	VerticalSide(String name, BracketSide side)
	{
		this.name = name;
		this.side = side;
	}

	public BracketSide bracketSide()
	{
		return side;
	}

	public VerticalSide opposite()
	{
		return this == TOP ? BOTTOM : TOP;
	}

	@Override
	public String toString()
	{
		return name;
	}
}

package com.vitalshud;

import java.awt.Color;
import java.util.Map;
import net.runelite.api.gameval.SpriteID;

/**
 * Everything the config says about one vital, gathered in one place.
 *
 * <p>The settings are per vital but the drawing code is not, so every reader
 * used to carry its own switch over the four - one for the side, one for the
 * colour, one for the threshold, and so on down to nine of them. Adding a
 * setting meant writing a tenth. Reading them all at once instead leaves the
 * switch in a single method and gives the drawing code plain fields.
 */
final class VitalSettings
{
	final BracketSide side;
	final Color color;
	final int threshold;

	final boolean showValue;

	final boolean showIcon;
	final int iconSize;
	final int iconX;
	final int iconY;

	private VitalSettings(BracketSide side, Color color, int threshold, boolean showValue,
		boolean showIcon, int iconSize, int iconX, int iconY)
	{
		this.side = side;
		this.color = color;
		this.threshold = threshold;
		this.showValue = showValue;
		this.showIcon = showIcon;
		this.iconSize = iconSize;
		this.iconX = iconX;
		this.iconY = iconY;
	}

	/**
	 * Reads the lot for every vital into the given map, which is refilled rather
	 * than replaced so a frame costs no allocation.
	 */
	static void read(VitalsHudConfig config, Map<VitalType, VitalSettings> settings)
	{
		settings.put(VitalType.HITPOINTS, new VitalSettings(
			config.hitpointsSide().bracketSide(), config.hitpointsColor(), config.hitpointsThreshold(),
			config.hitpointsBarValue(),
			config.hitpointsBarIcon(), config.hitpointsBarIconSize(),
			config.hitpointsBarIconX(), config.hitpointsBarIconY()));

		settings.put(VitalType.PRAYER, new VitalSettings(
			config.prayerSide().bracketSide(), config.prayerColor(), config.prayerThreshold(),
			config.prayerBarValue(),
			config.prayerBarIcon(), config.prayerBarIconSize(),
			config.prayerBarIconX(), config.prayerBarIconY()));

		settings.put(VitalType.RUN, new VitalSettings(
			config.runSide().bracketSide(), config.runColor(), config.runThreshold(),
			config.runBarValue(),
			config.runBarIcon(), config.runBarIconSize(),
			config.runBarIconX(), config.runBarIconY()));

		settings.put(VitalType.SPECIAL, new VitalSettings(
			config.specialSide().bracketSide(), config.specialColor(), config.specialThreshold(),
			config.specialBarValue(),
			config.specialBarIcon(), config.specialBarIconSize(),
			config.specialBarIconX(), config.specialBarIconY()));
	}

	/**
	 * The icon a vital's bar carries, by name.
	 *
	 * <p>Run energy is read live off its orb by the overlay, which tracks whatever
	 * the game shows without enumerating the cases. These stand in for the frames
	 * where the orb is not on screen to ask.
	 */
	static int sprite(VitalType type, boolean staminaActive)
	{
		switch (type)
		{
			case HITPOINTS:
				return SpriteID.OrbIcon.HITPOINTS;
			case PRAYER:
				return SpriteID.OrbIcon.PRAYER;
			case RUN:
				return staminaActive
					? SpriteID.OrbIcon.RUN_ICON_SLOWED_DEPLETION
					: SpriteID.OrbIcon.RUN;
			default:
				return SpriteID.OrbIcon.SPECIAL;
		}
	}
}

