import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws a bracket per vital around your character, plus the optional readouts
 * beside them.
 */
public class VitalsHudOverlay extends Overlay
{
	/**
	 * How far the poison and venom tints pull the hitpoints colour down.
	 */
	private static final float POISON_BLEND = 0.45f;
	private static final float VENOM_BLEND = 0.7f;

	/**
	 * How far a damage flash pulls the hitpoints bracket towards white.
	 */
	private static final float FLASH_BLEND = 0.6f;

	/**
	 * Length of one alert pulse, in milliseconds.
	 */
	private static final double PULSE_PERIOD = 900d;

	/**
	 * On-screen character height that the thickness, glow and text sizes are
	 * expressed against.
	 */
	private static final double REFERENCE_HEIGHT = 130d;

	/**
	 * Cap on a bracket's return, as a share of the frame's other side. Without it
	 * a tall narrow frame gives returns long enough to meet in the middle.
	 */
	private static final double MAX_FOOT = 0.4d;

	private static final float MIN_SCALE = 0.25f;
	private static final float MAX_SCALE = 6f;

	/**
	 * Alpha at which a pixel counts as part of a sprite rather than its padding.
	 */
	private static final int OPAQUE_ENOUGH = 24;

	/**
	 * How far a border reaches out from the artwork, in the sprite's own pixels.
	 * Measured before the sprite is scaled up to the bar, so the border grows
	 * with the icon rather than staying a hairline as you zoom.
	 */
	private static final int BORDER_REACH = 1;

	/**
	 * The fill range of a bracket that clears no corners: all of it.
	 */
	private static final float[] WHOLE_BRACKET = {0f, 1f};

	private final Client client;
	private final VitalsHudPlugin plugin;
	private final VitalsHudConfig config;
	private final SpriteManager spriteManager;

	/**
	 * Works out how big the character is on screen, which is what the brackets
	 * hang on.
	 */
	private final CharacterMeasure measure;

	/**
	 * Rebuilt in place each frame rather than allocated, since the render runs
	 * every frame and the list is at most four entries long.
	 */
	private final List<VitalType> segments = new ArrayList<>(VitalType.values().length);

	/**
	 * Values queued while the brackets are drawn and written afterwards, so they
	 * take the readouts' opacity rather than the brackets'.
	 */
	private final List<BarLabel> barLabels = new ArrayList<>(VitalType.values().length);

	/**
	 * Skill icons sitting on the bars, queued alongside the values so they take
	 * the same opacity.
	 */
	private final List<BarIcon> barIcons = new ArrayList<>(VitalType.values().length);

	/**
	 * Where each bracket sits this frame, for the icon rows to hang off.
	 */
	private Rectangle2D prayerBounds;
	private Rectangle2D hitpointsBounds;

	/**
	 * How big the character is on screen this frame, for the icon rows that
	 * choose to follow it.
	 */
	private float renderScale = 1f;

	/**
	 * Where each sprite's artwork sits inside its image, measured once and kept.
	 */
	private final Map<Integer, Point2D.Double> artCentres = new HashMap<>();

	/**
	 * Single-colour copies of the bar sprites, built on first use and kept, for
	 * lighting or tinting an icon without rebuilding an image every frame.
	 */
	private final Map<Long, BufferedImage> tintMasks = new HashMap<>();

	/**
	 * Bordered copies of the bar sprites, keyed by sprite and border colour so a
	 * recoloured border builds a new one rather than reusing the old.
	 */
	private final Map<Long, BufferedImage> borderMasks = new HashMap<>();

	/**
	 * What the config says about each vital, read once at the top of the frame so
	 * the drawing below is not asking the same questions over and over.
	 */
	private final Map<VitalType, VitalSettings> settings = new EnumMap<>(VitalType.class);

	/**
	 * Working maps rebuilt in place each frame rather than allocated, since the
	 * render runs every frame and each holds one entry per side.
	 */
	private final Map<BracketSide, Integer> sharing = new EnumMap<>(BracketSide.class);
	private final Map<BracketSide, Double> feet = new EnumMap<>(BracketSide.class);
	private final Map<BracketSide, Integer> placed = new EnumMap<>(BracketSide.class);

	@Inject
	private VitalsHudOverlay(Client client, VitalsHudPlugin plugin, VitalsHudConfig config,
		SpriteManager spriteManager)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.spriteManager = spriteManager;
		this.measure = new CharacterMeasure(client);

		setPosition(OverlayPosition.DYNAMIC);

		// Drawing above the world rather than into the scene keeps the brackets on
		// top of the model instead of being clipped by it.
		setLayer(OverlayLayer.UNDER_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return null;
		}

		VitalSettings.read(config, settings);

		refreshSegments();
		if (segments.isEmpty())
		{
			return null;
		}

		boolean combat = plugin.inCombat();
		boolean prayerOn = plugin.isPrayerActive();
		boolean hidden = config.hideOutOfCombat() && plugin.pastHideDelay();

		// An active prayer can keep either the prayer bracket or the whole set on
		// screen, so the drain is still visible after the rest would have gone.
		boolean holdAll = hidden && prayerOn && config.idleHold() == IdleHold.WHOLE_HUD;
		boolean holdPrayer = hidden && prayerOn && config.idleHold() == IdleHold.PRAYER_BAR;

		if (hidden && !holdAll && !holdPrayer)
		{
			return null;
		}

		Rectangle2D model = measure.bounds(local);
		if (model == null || model.getHeight() <= 0d)
		{
			return null;
		}

		// Thickness, glow and text follow how big the character is on screen, so a
		// distant character gets a proportionally lighter frame.
		float scale = (float) Math.max(MIN_SCALE,
			Math.min(MAX_SCALE, model.getHeight() / REFERENCE_HEIGHT));

		renderScale = scale;

		Rectangle2D frame = frame(model, config.scalePercent() / 100f);

		RenderingHints previousHints = graphics.getRenderingHints();
		applyQualityHints(graphics);

		Composite previousComposite = graphics.getComposite();
		float opacity = (combat ? config.activeOpacity() : config.restingOpacity()) / 100f;
		graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, Math.min(1f, opacity)));

		float thickness = Math.max(1f, config.thickness() * scale);
		int glow = config.glow();
		boolean anyLow = config.alertMode() == AlertMode.HUD && anyLow();

		placed.clear();
		refreshSideCounts();
		refreshFootLengths(frame);

		double clearance = thickness * 2.5d;

		barLabels.clear();
		barIcons.clear();
		prayerBounds = null;
		hitpointsBounds = null;

		for (VitalType type : segments)
		{
			if (hidden && !holdAll && type != VitalType.PRAYER)
			{
				continue;
			}

			BracketSide side = side(type);
			int stacked = placed.merge(side, 1, Integer::sum) - 1;

			Rectangle2D bounds = bracketFrame(frame, side, clearance, stacked);

			// Brackets sharing a side lose their returns. Nested returns turn a
			// stack into a staircase of hooks; plain lines read as parallel bars,
			// which is the only sensible thing several vitals on one side can be.
			double foot = sharing.get(side) > 1 ? 0d : feet.get(side);

			Shape bracket = OutlineRenderer.bracket(bounds, side, foot, config.cornerRadius() * scale);

			drawBracket(graphics, bracket, thickness, glow, type, anyLow,
				fillRange(bracket, side, foot, feet, clearance));

			if (type == VitalType.PRAYER)
			{
				prayerBounds = bounds;
			}
			else if (type == VitalType.HITPOINTS)
			{
				hitpointsBounds = bounds;
			}

			if (config.showBarValues())
			{
				queueBarValue(type, bounds, side);
			}

			queueBarIcon(type, bounds, side);
		}

		drawExtras(graphics);

		graphics.setComposite(previousComposite);
		graphics.setRenderingHints(previousHints);

		return null;
	}

	private void drawBracket(Graphics2D graphics, Shape bracket, float thickness, int glow,
		VitalType type, boolean hudAlert, float[] range)
	{
		VitalsHudPlugin.Reading reading = plugin.reading(type);
		if (reading == null)
		{
			return;
		}

		float fraction = plugin.meterState(type).advance(reading.fraction(), config.animate(),
			config.dropMillis(), config.recoverMillis());
		fraction = Math.max(0f, Math.min(1f, fraction));

		// The bracket is always drawn end to end; only the fill is held inside the
		// range, so the shape stays whole while the drain stops at its neighbours.
		if (config.showTrack())
		{
			OutlineRenderer.stroke(graphics, bracket, thickness, 0, config.trackColor());
		}

		// The preview sits past the current level, so it starts where the fill
		// stops rather than at the beginning of the bracket.
		if (plugin.getPreviewType() == type && plugin.getPreviewAmount() > 0)
		{
			float previewTop = Math.min(1f,
				(reading.current + plugin.getPreviewAmount()) / (float) reading.scale());

			if (previewTop > fraction)
			{
				OutlineRenderer.stroke(graphics,
					OutlineRenderer.subPath(bracket, at(range, fraction), at(range, previewTop)),
					thickness, 0, config.healPreviewColor());
			}
		}

		// Overheal takes only the stretch past your real maximum. Recolouring the
		// whole bracket instead made the hitpoints colour setting look broken
		// whenever a brew was up.
		float realMaxAt = -1f;
		if (type == VitalType.HITPOINTS && config.showOverheal() && reading.isOverhealed())
		{
			realMaxAt = reading.realMax / (float) reading.scale();
		}

		float mainTop = realMaxAt >= 0f ? Math.min(fraction, realMaxAt) : fraction;

		OutlineRenderer.stroke(graphics,
			OutlineRenderer.subPath(bracket, range[0], at(range, mainTop)),
			thickness, glow, segmentColor(type, reading, hudAlert));

		if (realMaxAt >= 0f && fraction > realMaxAt)
		{
			OutlineRenderer.stroke(graphics,
				OutlineRenderer.subPath(bracket, at(range, realMaxAt), at(range, fraction)),
				thickness, glow, config.overhealColor());
		}
	}

	/**
	 * Places a 0..1 level inside the stretch a bracket's fill may use.
	 */
	private static float at(float[] range, float level)
	{
		return range[0] + (range[1] - range[0]) * Math.max(0f, Math.min(1f, level));
	}

	/**
	 * The bracket's colour once overheal, the poison tint, a damage flash and any
	 * alert have been applied.
	 */
	private Color segmentColor(VitalType type, VitalsHudPlugin.Reading reading, boolean hudAlert)
	{
		Color color = configuredColor(type);

		// A weapon with nothing to spend the bar on makes the bar meaningless, so
		// it reads as unavailable rather than as a vital worth watching.
		if (type == VitalType.SPECIAL && config.greyOutNoSpecial() && config.specReadyFromWeapon()
			&& plugin.getSpecialCost() <= 0)
		{
			return config.specialIdleColor();
		}

		if (type == VitalType.HITPOINTS)
		{
			if (config.poisonTint())
			{
				int poison = plugin.getPoisonState();
				if (poison == 2)
				{
					color = OutlineRenderer.blend(color, config.venomColor(), VENOM_BLEND);
				}
				else if (poison == 1)
				{
					color = OutlineRenderer.blend(color, config.poisonColor(), POISON_BLEND);
				}
			}

			float flash = plugin.hitFlash();
			if (flash > 0f)
			{
				color = OutlineRenderer.blend(color, Color.WHITE, flash * FLASH_BLEND);
			}
		}

		boolean alert = config.alertMode() != AlertMode.OFF
			&& (hudAlert || (config.alertMode() == AlertMode.BAR && isLow(type, reading)));

		if (alert)
		{
			if (config.alertUseWarningColor())
			{
				color = config.alertWarningColor();
			}

			// The pulse dips below the configured brightness rather than rising
			// above it, so raising the strength never makes an alert wash out.
			color = OutlineRenderer.blend(color, Color.WHITE,
				config.alertBrighten() / 100f * (config.alertPulse() ? swing() : 1f));
		}
		else if (type == VitalType.SPECIAL && config.specReadyPulse()
			&& reading.current >= specReadyAt())
		{
			color = OutlineRenderer.blend(color, Color.WHITE, strength() * wave());
		}

		return color;
	}

	/**
	 * A 0..1 wave. Driven by the clock rather than frame count so the rate does
	 * not follow the frame rate.
	 */
	private static float wave()
	{
		double phase = System.currentTimeMillis() % PULSE_PERIOD / PULSE_PERIOD;
		return (float) (0.5d + 0.5d * Math.sin(phase * 2d * Math.PI));
	}

	private float strength()
	{
		return config.pulseStrength() / 100f;
	}

	/**
	 * The wave scaled to the configured strength and lifted so it peaks at one.
	 * At zero strength it holds steady; at full strength it swings the whole way.
	 */
	private float swing()
	{
		float strength = strength();
		return 1f - strength + strength * wave();
	}

	/**
	 * Which vitals get a bracket. Hitpoints and prayer are always in; the rest
	 * are opt-in.
	 */
	private void refreshSegments()
	{
		segments.clear();
		segments.add(VitalType.HITPOINTS);
		segments.add(VitalType.PRAYER);

		if (config.runEnabled())
		{
			segments.add(VitalType.RUN);
		}

		if (config.specialEnabled())
		{
			segments.add(VitalType.SPECIAL);
		}
	}

	private boolean anyLow()
	{
		for (VitalType type : segments)
		{
			VitalsHudPlugin.Reading reading = plugin.reading(type);
			if (reading != null && isLow(type, reading))
			{
				return true;
			}
		}

		return false;
	}

	private boolean isLow(VitalType type, VitalsHudPlugin.Reading reading)
	{
		return reading.fraction() * 100f < threshold(type);
	}

	// -------------------------------------------------------------- Measuring


	/**
	 * Notes a vital's value against the middle of its own bracket, to be written
	 * once the brackets are done.
	 */
	private void queueBarValue(VitalType type, Rectangle2D bounds, BracketSide side)
	{
		VitalsHudPlugin.Reading reading = plugin.reading(type);
		if (reading == null || !showsBarValue(type))
		{
			return;
		}

		String value = config.barValueStyle().format(reading.current, reading.max);
		if (value == null)
		{
			return;
		}

		// The value sits where that vital's icon sits, so moving the icon carries
		// the number with it and the two never have to be lined up twice. It holds
		// even with the icon switched off, leaving the number where it was placed.
		java.awt.Point anchor = barAnchor(type, bounds, side);

		barLabels.add(new BarLabel(value,
			config.matchTextColors() ? configuredColor(type) : Color.WHITE,
			anchor.x, anchor.y));
	}

	/**
	 * The point a vital's icon and value share: the middle of its bar, moved by
	 * that vital's nudges.
	 */
	private java.awt.Point barAnchor(VitalType type, Rectangle2D bounds, BracketSide side)
	{
		double x = side.isUpright() ? edgeX(bounds, side) : bounds.getCenterX();
		double y = side.isUpright() ? bounds.getCenterY() : edgeY(bounds, side);

		boolean scaleIcons = config.barIconsScale();

		return new java.awt.Point(
			(int) Math.round(x) + scaled(barIconX(type), scaleIcons),
			(int) Math.round(y) + scaled(barIconY(type), scaleIcons));
	}

	/**
	 * Notes a vital's skill icon on the middle of its own bar, to be drawn once
	 * the bars are done.
	 */
	private void queueBarIcon(VitalType type, Rectangle2D bounds, BracketSide side)
	{
		if (!showsBarIcon(type))
		{
			return;
		}

		int size = sized(barIconSize(type), config.barIconsScale());
		java.awt.Point anchor = barAnchor(type, bounds, side);

		// The anchor is where the artwork centres, which is also where the value
		// centres, so the two line up whatever padding the sprite carries.
		barIcons.add(new BarIcon(barSprite(type), anchor.x, anchor.y, size,
			iconBrightness(type), iconBorder(type), iconTint(type), iconTintStrength(type)));
	}

	private static double edgeX(Rectangle2D bounds, BracketSide side)
	{
		return side == BracketSide.LEFT ? bounds.getMinX() : bounds.getMaxX();
	}

	private static double edgeY(Rectangle2D bounds, BracketSide side)
	{
		return side == BracketSide.TOP ? bounds.getMinY() : bounds.getMaxY();
	}

	private void drawBarIcons(Graphics2D graphics)
	{
		for (BarIcon icon : barIcons)
		{
			BufferedImage image = spriteManager.getSprite(icon.sprite, 0);
			if (image != null)
			{
				drawIconCentred(graphics, icon.sprite, image, icon.x, icon.y, icon.size);
				brighten(graphics, icon, image);
			}
		}
	}

	/**
	 * Marks an icon while its vital is doing something.
	 *
	 * <p>Hitpoints washes towards white, since a hit is a moment rather than a
	 * state and a flash reads as one. Prayer and special attack instead take a
	 * border around the artwork, which holds for as long as they are on without
	 * washing the symbol out.
	 *
	 * <p>Either way it is a prepared copy of the sprite drawn over the original,
	 * so only the artwork is touched and its transparent padding stays clear.
	 * Recolouring the sprite itself would need a fresh image every frame as a
	 * fading flash moves; a copy kept per sprite does not.
	 */
	private void brighten(Graphics2D graphics, BarIcon icon, BufferedImage image)
	{
		// The tint goes on first, so a poisoned heart still flashes white over its
		// green rather than the other way about.
		if (icon.tint != null)
		{
			overlay(graphics, icon, image, tintMask(icon.sprite, image, icon.tint), icon.tintStrength);
		}

		if (icon.brightness <= 0f)
		{
			return;
		}

		// A border carries its own alpha in its colour, so the strength setting is
		// left to the wash it was written for. Held at full, a border faded to the
		// same degree as a flash would barely read as one.
		if (icon.border != null)
		{
			overlay(graphics, icon, image, borderMask(icon.sprite, image, icon.border), 1f);
			return;
		}

		overlay(graphics, icon, image, tintMask(icon.sprite, image, Color.WHITE), icon.brightness);
	}

	/**
	 * Lays a prepared copy of a sprite over the original at the given strength.
	 */
	private void overlay(Graphics2D graphics, BarIcon icon, BufferedImage image,
		BufferedImage mask, float strength)
	{
		if (mask == null || strength <= 0f)
		{
			return;
		}

		Composite previous = graphics.getComposite();

		// Folded into whatever opacity the readouts are already drawn at, rather
		// than replacing it, so a marked icon does not punch through a faded HUD.
		float carried = previous instanceof AlphaComposite
			? ((AlphaComposite) previous).getAlpha() : 1f;

		graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER,
			Math.min(1f, carried * strength)));

		drawIconCentred(graphics, icon.sprite, mask, icon.x, icon.y, icon.size);

		graphics.setComposite(previous);
	}

	/**
	 * A single-colour copy of a sprite carrying its original transparency, built
	 * once per sprite and colour and kept.
	 */
	private BufferedImage tintMask(int spriteId, BufferedImage icon, Color color)
	{
		long key = maskKey(spriteId, color);

		BufferedImage cached = tintMasks.get(key);
		if (cached != null)
		{
			return cached;
		}

		int width = icon.getWidth();
		int height = icon.getHeight();

		if (width <= 0 || height <= 0)
		{
			return null;
		}

		BufferedImage mask = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		int rgb = color.getRGB() & 0x00ffffff;

		for (int y = 0; y < height; y++)
		{
			for (int x = 0; x < width; x++)
			{
				mask.setRGB(x, y, (icon.getRGB(x, y) & 0xff000000) | rgb);
			}
		}

		tintMasks.put(key, mask);

		return mask;
	}

	/**
	 * Cache key for a prepared copy of a sprite in a given colour.
	 */
	private static long maskKey(int spriteId, Color color)
	{
		return ((long) spriteId << 32) | (color.getRGB() & 0xffffffffL);
	}

	/**
	 * A copy of a sprite holding only a border traced around its artwork, in the
	 * given colour.
	 *
	 * <p>The border is grown outwards into the sprite's own padding rather than
	 * onto a larger canvas, so the copy stays the same size as the original and
	 * lines up on the same centre without a second measurement. Artwork running
	 * hard to the edge of its image has no padding left to grow into, and loses
	 * its border along that edge.
	 */
	private BufferedImage borderMask(int spriteId, BufferedImage icon, Color color)
	{
		long key = maskKey(spriteId, color);

		BufferedImage cached = borderMasks.get(key);
		if (cached != null)
		{
			return cached;
		}

		int width = icon.getWidth();
		int height = icon.getHeight();

		if (width <= 0 || height <= 0)
		{
			return null;
		}

		BufferedImage mask = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		int rgb = color.getRGB() & 0x00ffffff;
		int alpha = (color.getAlpha() & 0xff) << 24;

		for (int y = 0; y < height; y++)
		{
			for (int x = 0; x < width; x++)
			{
				if (!opaque(icon, x, y) && touchesArtwork(icon, x, y))
				{
					mask.setRGB(x, y, alpha | rgb);
				}
			}
		}

		borderMasks.put(key, mask);

		return mask;
	}

	/**
	 * Whether a clear pixel has artwork within a step of it, which is what makes
	 * it part of the border.
	 */
	private static boolean touchesArtwork(BufferedImage icon, int x, int y)
	{
		for (int dy = -BORDER_REACH; dy <= BORDER_REACH; dy++)
		{
			for (int dx = -BORDER_REACH; dx <= BORDER_REACH; dx++)
			{
				if (opaque(icon, x + dx, y + dy))
				{
					return true;
				}
			}
		}

		return false;
	}

	private static boolean opaque(BufferedImage icon, int x, int y)
	{
		if (x < 0 || y < 0 || x >= icon.getWidth() || y >= icon.getHeight())
		{
			return false;
		}

		return (icon.getRGB(x, y) >>> 24) >= OPAQUE_ENOUGH;
	}

	/**
	 * How brightly a vital's icon should be lit, 0 for not at all.
	 *
	 * <p>Each vital lights for its own reason: hitpoints as a hit lands, fading
	 * with the same flash the bracket uses; prayer for as long as a prayer is on;
	 * special attack once it is armed.
	 */
	private float iconBrightness(VitalType type)
	{
		if (!config.barIconsBrighten())
		{
			return 0f;
		}

		float strength = config.barIconsBrightenStrength() / 100f;

		switch (type)
		{
			case HITPOINTS:
				return plugin.damageFade() * strength;
			case PRAYER:
				return plugin.isPrayerActive() ? strength : 0f;
			case SPECIAL:
				return client.getVarpValue(VarPlayerID.SA_ATTACK) == 1 ? strength : 0f;
			default:
				return 0f;
		}
	}

	/**
	 * The border colour a vital's icon takes while active, or null for the ones
	 * that wash towards white instead.
	 *
	 * <p>Prayer and special attack hold their state for as long as they are on,
	 * and a wash held that long buries the symbol underneath it. A border marks
	 * the icon while leaving it legible.
	 */
	private Color iconBorder(VitalType type)
	{
		return type == VitalType.PRAYER || type == VitalType.SPECIAL
			? config.barIconsBorderColor() : null;
	}

	/**
	 * The standing colour a vital's icon carries, or null for none. Only the
	 * heart has one: it goes the same green the bracket does while you are
	 * poisoned, so the two do not disagree about your state.
	 */
	private Color iconTint(VitalType type)
	{
		if (type != VitalType.HITPOINTS || !config.poisonTint())
		{
			return null;
		}

		switch (plugin.getPoisonState())
		{
			case 2:
				return config.venomColor();
			case 1:
				return config.poisonColor();
			default:
				return null;
		}
	}

	private float iconTintStrength(VitalType type)
	{
		if (iconTint(type) == null)
		{
			return 0f;
		}

		return plugin.getPoisonState() == 2 ? VENOM_BLEND : POISON_BLEND;
	}

	/**
	 * A skill icon waiting to be drawn, centred on its anchor.
	 */
	private static final class BarIcon
	{
		final int sprite;
		final int x;
		final int y;
		final int size;
		final float brightness;

		/**
		 * Colour of the border to mark this icon with, or null to wash it towards
		 * white instead.
		 */
		final Color border;

		/**
		 * A standing colour laid over the artwork, or null for none. Separate from
		 * the border and the wash because it says something else: poison is a state
		 * the vital is in rather than something it is doing.
		 */
		final Color tint;
		final float tintStrength;

		BarIcon(int sprite, int x, int y, int size, float brightness, Color border,
			Color tint, float tintStrength)
		{
			this.sprite = sprite;
			this.x = x;
			this.y = y;
			this.size = size;
			this.brightness = brightness;
			this.border = border;
			this.tint = tint;
			this.tintStrength = tintStrength;
		}
	}

	/**
	 * Which way is away from the character for a bracket on this side. Flat
	 * brackets have no sideways outward, and uprights none vertically.
	 */
	private static int outwardX(BracketSide side, int distance)
	{
		switch (side)
		{
			case LEFT:
				return -distance;
			case RIGHT:
				return distance;
			default:
				return 0;
		}
	}

	private static int outwardY(BracketSide side, int distance)
	{
		switch (side)
		{
			case TOP:
				return -distance;
			case BOTTOM:
				return distance;
			default:
				return 0;
		}
	}

	/**
	 * How many brackets each side is carrying.
	 */
	private void refreshSideCounts()
	{
		for (BracketSide side : BracketSide.values())
		{
			sharing.put(side, 0);
		}

		for (VitalType type : segments)
		{
			sharing.merge(side(type), 1, Integer::sum);
		}
	}

	/**
	 * The return length each side would use, worked out once so that a bracket can
	 * see how far its neighbours reach into the corners.
	 */
	private void refreshFootLengths(Rectangle2D frame)
	{
		for (BracketSide side : BracketSide.values())
		{
			double along = side.isUpright() ? frame.getHeight() : frame.getWidth();
			double across = side.isUpright() ? frame.getWidth() : frame.getHeight();

			// Capped against the other side so the two returns cannot reach far
			// enough to meet, which a tall narrow frame would otherwise do.
			feet.put(side, Math.min(along * (config.footLength() / 100d), across * MAX_FOOT));
		}
	}

	/**
	 * The stretch of a bracket its fill is allowed to use, as fractions of the
	 * bracket's length.
	 *
	 * <p>Where a neighbour reaches into a corner, the fill stops short of it. The
	 * bracket itself is still drawn end to end - only the coloured part is held
	 * back, so a drain empties from where the neighbouring bracket ends rather
	 * than from a corner hidden behind it.
	 *
	 * <p>Only the uprights give way. Doing the same for the flat brackets left
	 * them almost nothing to fill: an upright's return may run to nearly half the
	 * frame's width, so the two of them together claimed most of the top edge.
	 */
	private float[] fillRange(Shape bracket, BracketSide side, double foot,
		Map<BracketSide, Double> feet, double clearance)
	{
		double total = OutlineRenderer.length(bracket);
		if (!side.isUpright())
		{
			return WHOLE_BRACKET.clone();
		}

		// A bracket runs from the start of one return to the end of the other, so
		// clearing a corner means clearing this bracket's own return as well as
		// however far the neighbour reaches back along it.
		double lo = occupies(BracketSide.BOTTOM)
			? foot + feet.get(BracketSide.BOTTOM) + clearance : 0d;
		double hi = occupies(BracketSide.TOP)
			? foot + feet.get(BracketSide.TOP) + clearance : 0d;

		return fillRange(total, lo, hi);
	}

	/**
	 * The stretch left to the fill once the corners are cleared, as fractions of
	 * the bracket's length.
	 *
	 * <p>Clamped at both ends: a bracket keeps at least the middle tenth of
	 * itself however far its neighbours reach, since a fill with nowhere to go
	 * reads as a bracket that is simply broken.
	 *
	 * @param total the bracket's length, 0 or less if it has none
	 * @param lo    how far the fill is held off the start
	 * @param hi    how far the fill is held off the end
	 */
	static float[] fillRange(double total, double lo, double hi)
	{
		if (total <= 0d)
		{
			return WHOLE_BRACKET.clone();
		}

		float start = (float) Math.max(0d, Math.min(0.45d, lo / total));
		float end = (float) Math.max(0.55d, Math.min(1d, 1d - hi / total));

		return new float[]{start, end};
	}

	private boolean occupies(BracketSide side)
	{
		for (VitalType type : segments)
		{
			if (side(type) == side)
			{
				return true;
			}
		}

		return false;
	}

	/**
	 * The box one bracket is drawn on.
	 *
	 * <p>Every bracket sits on the full frame, so the four of them line up into one
	 * shape. The only adjustment is for brackets that would otherwise land on top
	 * of each other, which are pushed outwards instead.
	 *
	 * @param stacked how many brackets already share this side
	 */
	static Rectangle2D bracketFrame(Rectangle2D frame, BracketSide side, double clearance,
		int stacked)
	{
		if (stacked == 0)
		{
			return frame;
		}

		double x = frame.getX();
		double y = frame.getY();
		double width = frame.getWidth();
		double height = frame.getHeight();
		double push = stacked * clearance * 2d;

		if (side.isUpright())
		{
			if (side == BracketSide.LEFT)
			{
				x -= push;
			}

			width += push;
		}
		else
		{
			if (side == BracketSide.TOP)
			{
				y -= push;
			}

			height += push;
		}

		return new Rectangle2D.Double(x, y, Math.max(1d, width), Math.max(1d, height));
	}

	/**
	 * The brackets' box: the model's box grown by the width and height settings,
	 * about its own centre so it stays on the character.
	 */
	private Rectangle2D frame(Rectangle2D model, float scale)
	{
		double width = model.getWidth() * (config.frameWidth() / 100d) * scale;
		double height = model.getHeight() * (config.frameHeight() / 100d) * scale;

		return new Rectangle2D.Double(
			model.getCenterX() - width / 2d,
			model.getCenterY() - height / 2d,
			width,
			height);
	}


	/**
	 * Quality settings for the whole overlay.
	 *
	 * <p>Pure stroke control is the one that matters most: Java2D normalises
	 * strokes by default, which snaps a thin bracket's edges to the pixel grid.
	 */
	private static void applyQualityHints(Graphics2D graphics)
	{
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		graphics.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
		graphics.setRenderingHint(RenderingHints.KEY_ALPHA_INTERPOLATION,
			RenderingHints.VALUE_ALPHA_INTERPOLATION_QUALITY);
		graphics.setRenderingHint(RenderingHints.KEY_COLOR_RENDERING,
			RenderingHints.VALUE_COLOR_RENDER_QUALITY);
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
			RenderingHints.VALUE_INTERPOLATION_BILINEAR);

		// The value text uses the game's own pixel font, which smears when it is
		// antialiased. Left off, it stays crisp and matches the rest of the UI.
		graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
			RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
	}

	// ------------------------------------------------------------------ Extras

	/**
	 * The readouts under or over the brackets.
	 *
	 * <p>Deliberately drawn at a fixed size rather than scaled with the character:
	 * text and icons that shrink as you zoom out stop being readable, which is the
	 * opposite of what a readout is for. Only their position follows the frame.
	 *
	 * <p>They also carry their own opacity instead of the brackets', so a faded
	 * resting HUD does not drag the icons down with it.
	 */
	private void drawExtras(Graphics2D graphics)
	{
		Composite previous = graphics.getComposite();
		graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER,
			Math.min(1f, config.extrasOpacity() / 100f)));

		drawBarIcons(graphics);
		drawBarValues(graphics);
		drawAttachedPrayers(graphics);
		drawBoosts(graphics);

		graphics.setComposite(previous);
	}

	private void drawBarValues(Graphics2D graphics)
	{
		int size = sized(config.barValueSize(), config.barValueScale());

		for (BarLabel label : barLabels)
		{
			drawCentredOn(graphics, label.text, label.x, label.y, label.color, size);
		}
	}

	/**
	 * The prayers attached to the prayer bracket: alongside an upright as a
	 * column, above or below a flat one as a row, and always on the outside.
	 */
	private void drawAttachedPrayers(Graphics2D graphics)
	{
		if (!config.showPrayers() || prayerBounds == null)
		{
			return;
		}

		List<Prayer> active = visiblePrayers();
		if (active.isEmpty())
		{
			return;
		}

		BracketSide side = config.prayerSide().bracketSide();
		int chip = sized(config.prayerChipSize(), config.prayerScaleWithCharacter());

		int[] origin = attachedOrigin(prayerBounds, side, chip, active.size(),
			config.prayerDistance(), config.prayerNudgeX(), config.prayerNudgeY());

		drawPrayers(graphics, origin[0], origin[1], chip, side.isUpright());
	}

	/**
	 * The potion effects running, drawn against the hitpoints bracket in the same
	 * way the prayers are drawn against theirs.
	 */
	/**
	 * The combat levels, each on its own skill icon, attached to the hitpoints
	 * bracket in the same way the prayers attach to theirs.
	 */
	private void drawBoosts(Graphics2D graphics)
	{
		if (hitpointsBounds == null)
		{
			return;
		}

		List<IconEntry> entries = boostEntries();
		if (entries.isEmpty())
		{
			return;
		}

		BracketSide side = config.hitpointsSide().bracketSide();
		int size = sized(config.boostIconSize(), config.boostScaleWithCharacter());
		int labelSize = sized(config.boostLabelSize(), config.boostScaleWithCharacter());
		boolean vertical = side.isUpright();
		int spacing = size + Math.max(3, size / 4);

		// Wrapped into a grid rather than run out in one line: five icons in a
		// single file end up taller than the character they belong to.
		int perLine = Math.max(1, config.boostWrap());
		int[] origin = attachedOrigin(hitpointsBounds, side, size, Math.min(entries.size(), perLine),
			config.boostDistance(), config.boostNudgeX(), config.boostNudgeY());

		// Later lines step further away from the character rather than across it.
		int step = vertical
			? (side == BracketSide.LEFT ? -spacing : spacing)
			: (side == BracketSide.TOP ? -spacing : spacing);

		for (int i = 0; i < entries.size(); i++)
		{
			IconEntry entry = entries.get(i);

			int line = i / perLine;
			int slot = i % perLine;

			int x = origin[0] + (vertical ? line * step : slot * spacing);
			int y = origin[1] + (vertical ? slot * spacing : line * step);

			if (vertical)
			{
				x -= size / 2;
			}

			// A sprite that has not been cached yet comes back null for a frame or
			// two, so the number is still written even when the icon is missing.
			// Centred on the artwork rather than the image, so a sprite with uneven
			// padding does not leave its number sitting off to one side.
			int centreX = x + size / 2;
			int centreY = y + size / 2;

			BufferedImage icon = spriteManager.getSprite(entry.sprite, 0);
			if (icon != null)
			{
				drawIconCentred(graphics, entry.sprite, icon, centreX, centreY, size);
			}

			drawCentredOn(graphics, entry.text, centreX, centreY, entry.color, labelSize);
		}
	}

	/**
	 * The icons to draw beside the hitpoints bracket: a combat level each, and the
	 * slayer task count if it is wanted. They share one row so that turning either
	 * on does not push the other around.
	 */
	private List<IconEntry> boostEntries()
	{
		List<IconEntry> entries = new ArrayList<>();

		if (config.showBoosts())
		{
			for (VitalsHudPlugin.StatBoost boost : plugin.getBoosts())
			{
				entries.add(new IconEntry(boost.skill.sprite(), String.valueOf(boost.boosted),
					boostColor(boost.skill)));
			}
		}

		// No task means nothing to count, so the icon stays away rather than
		// sitting there reading zero.
		if (config.showSlayerCount() && plugin.getSlayerCount() > 0)
		{
			entries.add(new IconEntry(SpriteID.Staticons2.SLAYER,
				String.valueOf(plugin.getSlayerCount()), config.slayerCountColor()));
		}

		return entries;
	}

	/**
	 * One icon with a number over it.
	 */
	private static final class IconEntry
	{
		final int sprite;
		final String text;
		final Color color;

		IconEntry(int sprite, String text, Color color)
		{
			this.sprite = sprite;
			this.text = text;
			this.color = color;
		}
	}

	/**
	 * A configured size, optionally grown or shrunk to keep pace with how big the
	 * character is on screen.
	 */
	private int sized(int size, boolean follow)
	{
		return follow ? Math.max(1, Math.round(size * renderScale)) : size;
	}

	/**
	 * The same, for an offset rather than a size.
	 *
	 * <p>Kept apart from {@link #sized} because that one floors at one pixel, which
	 * a size wants and an offset very much does not - it turned every negative
	 * nudge into a nudge of one in the opposite direction.
	 */
	private int scaled(int offset, boolean follow)
	{
		return follow ? Math.round(offset * renderScale) : offset;
	}

	/**
	 * Each skill's level takes its own colour, so which icon you are looking at
	 * reads from the number alone.
	 */
	private Color boostColor(BoostedSkill skill)
	{
		switch (skill)
		{
			case ATTACK:
				return config.attackLevelColor();
			case STRENGTH:
				return config.strengthLevelColor();
			case DEFENCE:
				return config.defenceLevelColor();
			case RANGED:
				return config.rangedLevelColor();
			default:
				return config.magicLevelColor();
		}
	}

	/**
	 * Where a run of icons attached to a bracket starts.
	 *
	 * <p>Centred on the bracket along its own run and pushed clear of it across
	 * the other axis, so a column beside an upright and a row above a flat one
	 * both come out centred on the character.
	 *
	 * @return the starting x and y
	 */
	private static int[] attachedOrigin(Rectangle2D bounds, BracketSide side, int size, int count,
		int distance, int nudgeX, int nudgeY)
	{
		int gap = Math.max(3, size / 4);
		int span = count * (size + gap) - gap;

		double anchorX = side == BracketSide.LEFT ? bounds.getMinX()
			: side == BracketSide.RIGHT ? bounds.getMaxX() : bounds.getCenterX();
		double anchorY = side == BracketSide.TOP ? bounds.getMinY()
			: side == BracketSide.BOTTOM ? bounds.getMaxY() : bounds.getCenterY();

		int x = (int) Math.round(anchorX) + outwardX(side, distance) + nudgeX;
		int y = (int) Math.round(anchorY) + outwardY(side, distance) + nudgeY;

		if (side.isUpright())
		{
			y -= span / 2;
			x += side == BracketSide.LEFT ? -size / 2 : size / 2;
		}
		else
		{
			x -= span / 2;
			y -= size / 2;
		}

		return new int[]{x, y};
	}

	/**
	 * Sets the configured face, turning smoothing on only for the one font that
	 * wants it. The game's own faces are pixel fonts and smear when smoothed.
	 */
	private void applyFont(Graphics2D graphics, int size)
	{
		TextFont font = config.textFont();

		graphics.setFont(font.font(size));
		graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
			font.antialias() ? RenderingHints.VALUE_TEXT_ANTIALIAS_ON
				: RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
	}


	/**
	 * The prayers currently on, drawn with the game's own icons where it has one
	 * and a lettered chip where it does not.
	 */
	/**
	 * @param centerX centre of the row, or of each entry when stacked vertically
	 * @param y       top of the first entry
	 */
	private void drawPrayers(Graphics2D graphics, int centerX, int y, int size, boolean vertical)
	{
		List<Prayer> active = visiblePrayers();
		if (active.isEmpty())
		{
			return;
		}

		int gap = Math.max(3, size / 4);
		int spacing = size + gap;

		int x = vertical ? centerX - size / 2 : centerX - (active.size() * spacing - gap) / 2;

		Font previous = graphics.getFont();
		graphics.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD, size * 0.62f));
		FontMetrics metrics = graphics.getFontMetrics();

		for (Prayer prayer : active)
		{
			BufferedImage icon = icon(prayer);

			if (icon != null)
			{
				drawIcon(graphics, icon, x, y, size);
			}
			else
			{
				drawPrayerChip(graphics, prayer, x, y, size, metrics);
			}

			if (vertical)
			{
				y += spacing;
			}
			else
			{
				x += spacing;
			}
		}

		graphics.setFont(previous);
	}

	/**
	 * A value waiting to be written beside its bracket.
	 */
	private static final class BarLabel
	{
		final String text;
		final Color color;
		final int x;
		final int y;

		BarLabel(String text, Color color, int x, int y)
		{
			this.text = text;
			this.color = color;
			this.x = x;
			this.y = y;
		}
	}

	/**
	 * Fits an icon inside its square without distorting it.
	 *
	 * <p>Prayer sprites are not square, so stretching one to fill the box squashed
	 * it. Scaling by the tighter of the two axes and centring what is left keeps
	 * the artwork's proportions.
	 */
	private static void drawIcon(Graphics2D graphics, BufferedImage icon, int x, int y, int size)
	{
		int width = icon.getWidth();
		int height = icon.getHeight();

		if (width <= 0 || height <= 0)
		{
			return;
		}

		double fit = Math.min(size / (double) width, size / (double) height);
		int drawWidth = Math.max(1, (int) Math.round(width * fit));
		int drawHeight = Math.max(1, (int) Math.round(height * fit));

		graphics.drawImage(icon, x + (size - drawWidth) / 2, y + (size - drawHeight) / 2,
			drawWidth, drawHeight, null);
	}

	/**
	 * Draws an icon with its artwork centred on a point.
	 *
	 * <p>A sprite is rarely centred inside its own image - the heart carries more
	 * transparent padding on one side than the other - so centring the image box
	 * leaves the symbol itself off centre, and a number centred on the same point
	 * looks wrong against it. Measuring where the opaque pixels actually sit fixes
	 * every sprite at once rather than nudging each one by hand.
	 */
	private void drawIconCentred(Graphics2D graphics, int spriteId, BufferedImage icon,
		int centerX, int centerY, int size)
	{
		int width = icon.getWidth();
		int height = icon.getHeight();

		if (width <= 0 || height <= 0)
		{
			return;
		}

		double fit = Math.min(size / (double) width, size / (double) height);
		int drawWidth = Math.max(1, (int) Math.round(width * fit));
		int drawHeight = Math.max(1, (int) Math.round(height * fit));

		Point2D.Double art = artCentre(spriteId, icon);

		graphics.drawImage(icon,
			centerX - (int) Math.round(art.x * drawWidth),
			centerY - (int) Math.round(art.y * drawHeight),
			drawWidth, drawHeight, null);
	}

	/**
	 * Where a sprite's visible artwork sits within its image, as a fraction of the
	 * image's width and height. Measured once per sprite and kept.
	 */
	private Point2D.Double artCentre(int spriteId, BufferedImage icon)
	{
		return artCentres.computeIfAbsent(spriteId, id -> measureArtCentre(icon));
	}

	/**
	 * Measures where a sprite's visible artwork sits within its image.
	 */
	static Point2D.Double measureArtCentre(BufferedImage icon)
	{
		int width = icon.getWidth();
		int height = icon.getHeight();

		int minX = width;
		int minY = height;
		int maxX = -1;
		int maxY = -1;

		for (int y = 0; y < height; y++)
		{
			for (int x = 0; x < width; x++)
			{
				if ((icon.getRGB(x, y) >>> 24) < OPAQUE_ENOUGH)
				{
					continue;
				}

				minX = Math.min(minX, x);
				minY = Math.min(minY, y);
				maxX = Math.max(maxX, x);
				maxY = Math.max(maxY, y);
			}
		}

		// A sprite that is entirely transparent, or has not finished loading, has
		// no artwork to measure; its own middle will do.
		return maxX < 0
			? new Point2D.Double(0.5d, 0.5d)
			: new Point2D.Double((minX + maxX + 1) / 2d / width, (minY + maxY + 1) / 2d / height);
	}

	private BufferedImage icon(Prayer prayer)
	{
		Integer spriteId = PrayerIcons.spriteId(prayer);

		// A sprite that has not been loaded yet comes back null; the chip stands in
		// until it arrives rather than leaving a gap in the row.
		return spriteId == null ? null : spriteManager.getSprite(spriteId, 0);
	}

	private void drawPrayerChip(Graphics2D graphics, Prayer prayer, int x, int y, int size,
		FontMetrics metrics)
	{
		// Near solid: the row carries its own opacity now, so the chip does not
		// need to be translucent to keep from shouting.
		graphics.setColor(OutlineRenderer.withAlpha(ActivePrayers.color(prayer), 235));
		graphics.fill(new RoundRectangle2D.Float(x, y, size, size, 4f, 4f));

		graphics.setColor(new Color(0, 0, 0, 150));
		graphics.setStroke(new BasicStroke(1f));
		graphics.draw(new RoundRectangle2D.Float(x, y, size, size, 4f, 4f));

		String label = ActivePrayers.label(prayer);
		int textX = x + (size - metrics.stringWidth(label)) / 2;
		int textY = y + (size + metrics.getAscent() - metrics.getDescent()) / 2;

		graphics.setColor(Color.BLACK);
		graphics.drawString(label, textX + 1, textY + 1);
		graphics.setColor(Color.WHITE);
		graphics.drawString(label, textX, textY);
	}

	/**
	 * The prayers to show, which by default leaves out the ones the game already
	 * draws over your head so the icons are not saying the same thing twice.
	 */
	private List<Prayer> visiblePrayers()
	{
		List<Prayer> active = plugin.getActivePrayers();

		if (!config.hideOverheadPrayers())
		{
			return active;
		}

		List<Prayer> visible = new ArrayList<>(active.size());

		for (Prayer prayer : active)
		{
			if (!ActivePrayers.isOverhead(prayer))
			{
				visible.add(prayer);
			}
		}

		return visible;
	}

	/**
	 * Writes text centred on a point, horizontally and vertically.
	 *
	 * <p>A string is placed by its baseline, which sits below the middle of the
	 * letters, so putting the baseline on the point leaves the text low. The
	 * offset has to come from the font's own ascent and descent - guessing it from
	 * the font size is close but visibly off, which is what left a value sitting
	 * low on its icon.
	 */
	private void drawCentredOn(Graphics2D graphics, String text, int centerX, int centerY,
		Color color, int size)
	{
		Font previousFont = graphics.getFont();
		Object previousHint = graphics.getRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING);
		applyFont(graphics, size);

		FontMetrics metrics = graphics.getFontMetrics();

		drawText(graphics, text, centerX - metrics.stringWidth(text) / 2,
			centerY + (metrics.getAscent() - metrics.getDescent()) / 2, color);

		graphics.setFont(previousFont);
		graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, previousHint);
	}

	/**
	 * Writes a value with a dark outline behind it.
	 *
	 * <p>The outline is laid down by drawing the same text in every direction
	 * around the centre, which is crude but the only way to outline a string in
	 * Java2D without building a glyph outline for it. The offsets are kept inside
	 * a circle so a thick setting stays round rather than turning square, and the
	 * corners of the square are skipped, which halves the work.
	 */
	private void drawText(Graphics2D graphics, String text, int x, int y, Color color)
	{
		int outline = config.textOutline();

		if (outline > 0)
		{
			double limit = (outline + 0.5d) * (outline + 0.5d);
			graphics.setColor(config.textOutlineColor());

			for (int dx = -outline; dx <= outline; dx++)
			{
				for (int dy = -outline; dy <= outline; dy++)
				{
					if ((dx != 0 || dy != 0) && dx * dx + dy * dy <= limit)
					{
						graphics.drawString(text, x + dx, y + dy);
					}
				}
			}
		}

		graphics.setColor(color);
		graphics.drawString(text, x, y);
	}

	// ------------------------------------------------------- Per-vital settings

	/**
	 * That vital's settings as of this frame.
	 */
	private VitalSettings settings(VitalType type)
	{
		return settings.get(type);
	}

	private Color configuredColor(VitalType type)
	{
		return settings(type).color;
	}

	private int threshold(VitalType type)
	{
		return settings(type).threshold;
	}

	/**
	 * The special attack energy that counts as ready: what the weapon in your hand
	 * would actually spend, falling back to the fixed percentage when that weapon
	 * is not in the table.
	 */
	private int specReadyAt()
	{
		int cost = plugin.getSpecialCost();

		return config.specReadyFromWeapon() && cost > 0 ? cost : config.specReadyAt();
	}

	/**
	 * The icon a vital's bar carries.
	 *
	 * <p>Run energy is read off its orb rather than named. Every state it has is
	 * in fact named - walking, running, and running while a stamina is up - but
	 * asking the orb tracks whatever the game decides to show without this having
	 * to enumerate the cases, and the named set stands in whenever the orb is not
	 * on screen to ask.
	 *
	 * <p>Prayer swaps to the game's own lit icon while a prayer is on, which reads
	 * as part of the interface in a way a drawn effect cannot.
	 */
	private int barSprite(VitalType type)
	{
		int named = VitalSettings.sprite(type, client.getVarbitValue(VarbitID.STAMINA_ACTIVE) > 0);

		if (type == VitalType.PRAYER)
		{
			return config.prayerIconActivated() && plugin.isPrayerActive()
				? SpriteID.OrbIcon.PRAYER_ICON_ACTIVATED : named;
		}

		if (type != VitalType.RUN)
		{
			return named;
		}

		Widget icon = client.getWidget(InterfaceID.Orbs.RUNENERGY_ICON);

		return icon == null || icon.getSpriteId() <= 0 ? named : icon.getSpriteId();
	}

	private boolean showsBarIcon(VitalType type)
	{
		return settings(type).showIcon;
	}

	private int barIconSize(VitalType type)
	{
		return settings(type).iconSize;
	}

	private int barIconX(VitalType type)
	{
		return settings(type).iconX;
	}

	private int barIconY(VitalType type)
	{
		return settings(type).iconY;
	}

	private boolean showsBarValue(VitalType type)
	{
		return settings(type).showValue;
	}

	private BracketSide side(VitalType type)
	{
		return settings(type).side;
	}
}

