@Slf4j
@PluginDescriptor(
	name = "Vitals Outline",
	description = "Brackets around your character that drain with hitpoints, prayer and run energy",
	tags = {"hitpoints", "prayer", "run", "energy", "outline", "highlight", "vitals"}
)
public class VitalsHudPlugin extends Plugin
{
	/**
	 * The poison varp counts upwards for poison and jumps past this once the
	 * damage becomes venom.
	 */
	private static final int VENOM_THRESHOLD = 1000000;

	/**
	 * Special attack energy is stored in tenths of a percent.
	 */
	private static final int SPECIAL_SCALE = 10;

	/**
	 * How long the damage flash lasts.
	 */
	private static final long FLASH_MILLIS = 350L;

	/**
	 * Items that make prayer potions restore more. Matched on name so that the
	 * imbued and upgraded variants are all covered by one entry.
	 */
	private static final String[] HOLY_WRENCH_ITEMS = {"holy wrench", "ring of the gods (i)",
		"prayer cape", "max cape"};

	/**
	 * Settings from earlier versions of this plugin that no longer exist. They
	 * are cleared once on start-up so an old profile does not carry dead keys
	 * around forever.
	 */
	private static final String[] RETIRED_KEYS = {
		"hitpointsEnabled", "prayerEnabled",
		"hitpointsShape", "hitpointsFill", "hitpointsPattern",
		"prayerShape", "prayerFill", "prayerPattern",
		"specialShape", "specialFill", "specialPattern",
		"runShape", "runFill", "runPattern",
		"offsetX", "offsetY", "gap", "barLength", "barThickness", "barSpacing", "altDrag",
		"shape", "fill", "pattern", "pipCount", "barEnds", "outline", "outlineColor", "shadow",
		"hitpointsDetached", "hitpointsDetachedX", "hitpointsDetachedY",
		"prayerDetached", "prayerDetachedX", "prayerDetachedY",
		"specialDetached", "specialDetachedX", "specialDetachedY",
		"runDetached", "runDetachedX", "runDetachedY",
		"bodyFit", "bodyWidth", "bodyHeight", "roundness", "outlineShape",
		"startAngle", "segmentGap", "expand", "mirrorWithCamera",
		"scaleWithZoom", "scaleWithCharacter", "useModelOutline", "modelTrim",
		"swingTimer", "swingTimerColor",
		"barValueDirection", "prayerDirection",
		"showTargetBar", "targetLabel", "targetColor",
		"showBuffTimers", "showBuffs", "buffIconSize", "buffWrap", "buffLabel",
		"buffTimerSize", "buffDistance", "buffNudgeX", "buffNudgeY",
		"boostedColor", "drainedColor", "levelColor",
		"barValueDistance", "hitpointsValueX", "hitpointsValueY",
		"prayerValueX", "prayerValueY", "runValueX", "runValueY",
		"specialValueX", "specialValueY",
		"showValueRow", "hitpointsRowValue", "prayerRowValue", "runRowValue", "specialRowValue",
