	};

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private VitalsHudConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private VitalsHudOverlay overlay;

	private final Map<VitalType, MeterState> meters = new EnumMap<>(VitalType.class);
	private final Map<VitalType, Reading> readings = new EnumMap<>(VitalType.class);

	/**
	 * Vitals already below their threshold, so the alert sound fires on the way
	 * down and then stays quiet until the vital has recovered.
	 */
	private final Set<VitalType> lowVitals = EnumSet.noneOf(VitalType.class);

	/**
	 * Prayers currently on. Rebuilt once a tick rather than per frame, since the
	 * overlay would otherwise walk the whole prayer list every time it draws.
	 */
	private List<Prayer> activePrayers = Collections.emptyList();

	/**
	 * The combat levels worth showing, rebuilt once a tick.
	 */
	private List<StatBoost> boosts = Collections.emptyList();

	/**
	 * Kills left on the current slayer task, or 0 when there is no task.
	 */
	@Getter
	private int slayerCount;

	@Getter
	private int poisonState;

	/**
	 * Whether any prayer is on, kept separately from the row above so the hide
	 * rules work even when the row itself is switched off.
	 */
	@Getter
	private boolean prayerActive;

	/**
	 * Vital the hovered item would restore, and by how much. Null when nothing
	 * useful is under the cursor.
	 */
	@Getter
	private VitalType previewType;

	@Getter
	private int previewAmount;

	private boolean holyWrench;

	/**
	 * What the equipped weapon's special attack costs, or 0 when it has none the
	 * table knows about.
	 */
	@Getter
	private int specialCost;

	/**
	 * Zero rather than {@link Long#MIN_VALUE}: subtracting the latter from the
	 * clock overflows, and the negative result read as "no time has passed", so
	 * anyone who had not fought yet counted as permanently in combat and the
	 * out-of-combat hide never fired.
	 */
	private long lastCombatMillis;
	private long lastDamageMillis;

	@Override
	protected void startUp()
	{
		for (VitalType type : VitalType.values())
		{
			meters.put(type, new MeterState());
		}

		clearRetiredSettings();
		overlayManager.add(overlay);

		clientThread.invoke(() ->
		{
			updateEquipment();
			refresh();
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);

		meters.clear();
		readings.clear();
		lowVitals.clear();
		activePrayers = Collections.emptyList();
		boosts = Collections.emptyList();
		previewType = null;
		previewAmount = 0;
		holyWrench = false;
	}

	private void clearRetiredSettings()
	{
		for (String key : RETIRED_KEYS)
		{
			if (configManager.getConfiguration(VitalsHudConfig.GROUP, key) != null)
			{
				configManager.unsetConfiguration(VitalsHudConfig.GROUP, key);
				log.debug("Cleared retired setting {}", key);
			}
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		refresh();
	}

	/**
	 * Keeps the pairs that share an axis on opposite sides.
	 *
	 * <p>Hitpoints and prayer hold the two flanks between them, special attack and
	 * run energy the two ends. Moving one onto its partner's side pushes that
	 * partner across rather than letting both pile onto one side, so the four can
	 * be rearranged without ever having to clear a side first.
	 */
	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!VitalsHudConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		switch (event.getKey())
		{
			case "hitpointsSide":
				if (config.hitpointsSide() == config.prayerSide())
				{
					set("prayerSide", config.hitpointsSide().opposite());
				}
				break;

			case "prayerSide":
				if (config.prayerSide() == config.hitpointsSide())
				{
					set("hitpointsSide", config.prayerSide().opposite());
				}
				break;

			case "specialSide":
				if (config.specialSide() == config.runSide())
				{
					set("runSide", config.specialSide().opposite());
				}
				break;

			case "runSide":
				if (config.runSide() == config.specialSide())
				{
					set("specialSide", config.runSide().opposite());
				}
				break;

			default:
				break;
		}
	}

	/**
	 * Writing the partner's side raises another change event, but by then the two
	 * differ, so the swap settles rather than bouncing back and forth.
	 */
	private void set(String key, Object value)
	{
		configManager.setConfiguration(VitalsHudConfig.GROUP, key, value);
		log.debug("Moved {} to {} to keep the pair apart", key, value);
	}

	/**
	 * The hovered item is read every client tick rather than every game tick.
	 * The menu is rebuilt as the cursor moves, so reading it on the game tick
	 * left the preview trailing the cursor by up to six hundred milliseconds.
	 */
	@Subscribe
	public void onClientTick(ClientTick event)
	{
		updatePreview();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();

		if (state == GameState.LOGGED_IN || state == GameState.HOPPING || state == GameState.LOADING)
		{
			// Draining from wherever the segments were before a world change looks
			// like a phantom hit, so start them at the real value instead.
			for (MeterState meter : meters.values())
			{
				meter.reset();
			}

			lowVitals.clear();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.WORN)
		{
			updateEquipment();
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return;
		}

		Hitsplat hitsplat = event.getHitsplat();
		boolean onMe = event.getActor() == local;

		// Damage dealt counts as combat too - attacking something that has not hit
		// back yet should still keep the brackets bright.
		if (onMe || hitsplat.isMine())
		{
			lastCombatMillis = System.currentTimeMillis();
		}

		if (onMe && hitsplat.getAmount() > 0)
		{
			lastDamageMillis = System.currentTimeMillis();
		}
	}

	private void refresh()
	{
		readings.put(VitalType.HITPOINTS, skillReading(Skill.HITPOINTS));
		readings.put(VitalType.PRAYER, skillReading(Skill.PRAYER));
		readings.put(VitalType.RUN, new Reading(runEnergy(), 100, 100));
		readings.put(VitalType.SPECIAL, new Reading(
			client.getVarpValue(VarPlayerID.SA_ENERGY) / SPECIAL_SCALE, 100, 100));

		slayerCount = client.getVarpValue(VarPlayerID.SLAYER_COUNT);

		updateCombat();
		updatePoison();
		updatePrayers();
		updateBoosts();
		updateAlerts();
	}

	private Reading skillReading(Skill skill)
	{
		return new Reading(client.getBoostedSkillLevel(skill), client.getRealSkillLevel(skill),
			client.getRealSkillLevel(skill));
	}

	/**
	 * Run energy is published in hundredths of a percent, but has not always
	 * been; scaling only when the value is out of range works either way.
	 */
	private int runEnergy()
	{
		int energy = client.getEnergy();
		return energy > 100 ? energy / 100 : energy;
	}

	/**
	 * Engaging something counts as combat in its own right. Waiting for a hitsplat
	 * left the brackets dim through the opening moments of a fight, which is
	 * exactly when they are worth looking at.
	 */
	private void updateCombat()
	{
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return;
		}

		if (isFighting(local.getInteracting()) || isFighting(findAttacker(local)))
		{
			lastCombatMillis = System.currentTimeMillis();
		}
	}

	private Actor findAttacker(Player local)
	{
		Actor interacting = local.getInteracting();
		return interacting != null && interacting.getInteracting() == local ? interacting : null;
	}

	private static boolean isFighting(Actor actor)
	{
		if (!(actor instanceof NPC))
		{
			return false;
		}

		NPCComposition composition = ((NPC) actor).getTransformedComposition();
		if (composition == null)
		{
			return false;
		}

		if (composition.getCombatLevel() > 0)
		{
			return true;
		}

		String[] actions = composition.getActions();
		if (actions == null)
		{
			return false;
		}

		for (String action : actions)
		{
			if ("Attack".equals(action))
			{
				return true;
			}
		}

		return false;
	}

	private void updatePoison()
	{
		int poison = client.getVarpValue(VarPlayerID.POISON);

		if (poison >= VENOM_THRESHOLD)
		{
			poisonState = 2;
		}
		else if (poison > 0)
		{
			poisonState = 1;
		}
		else
		{
			poisonState = 0;
		}
	}

	/**
	 * Whether anything is active is tracked even when the row is switched off,
	 * because the out-of-combat hide uses it to decide what to keep on screen.
	 */
	private void updatePrayers()
	{
		boolean showRow = config.showPrayers();
		List<Prayer> active = showRow ? new ArrayList<>() : null;

		prayerActive = false;

		for (Prayer prayer : Prayer.values())
		{
			// Read through the varbit rather than isPrayerActive, which is deprecated.
			if (client.getVarbitValue(prayer.getVarbit()) != 1)
			{
				continue;
			}

			prayerActive = true;

			if (active == null)
			{
				break;
			}

			active.add(prayer);
		}

		activePrayers = active == null ? Collections.emptyList() : active;
	}

	/**
	 * Collects the potion effects that are running.
	 *
	 * <p>Each is a varbit the game counts down, so any non-zero value means the
	 * effect is up - there is no need to know what the number means. Poison
	 * immunity is the odd one out: it shows as a negative poison value rather
	 * than a timer of its own.
	 */
	/**
	 * Collects the combat levels worth showing.
	 *
	 * <p>Reads the levels themselves rather than tracking what changed them, so a
	 * potion, an imbued heart and a rock cake all register the same way and
	 * nothing has to know which is which.
	 */
	private void updateBoosts()
	{
		if (!config.showBoosts())
		{
			boosts = Collections.emptyList();
			return;
		}

		List<StatBoost> current = new ArrayList<>(BoostedSkill.values().length);

		for (BoostedSkill skill : BoostedSkill.values())
		{
			int boosted = client.getBoostedSkillLevel(skill.skill());
			int real = client.getRealSkillLevel(skill.skill());

			if (boosted != real || config.showUnboosted())
			{
				current.add(new StatBoost(skill, boosted, real));
			}
		}

		boosts = current;
	}

	/**
	 * A combat skill's current level against what it should be.
	 */
	static final class StatBoost
	{
		final BoostedSkill skill;
		final int boosted;
		final int real;

		StatBoost(BoostedSkill skill, int boosted, int real)
		{
			this.skill = skill;
			this.boosted = boosted;
			this.real = real;
		}
	}


	/**
	 * Sounds once as a vital crosses its threshold downwards. Crossing back up
	 * rearms it, so a stat hovering on the line does not chatter.
	 */
	private void updateAlerts()
	{
		for (VitalType type : VitalType.values())
		{
			Reading reading = readings.get(type);
			if (reading == null)
			{
				continue;
			}

			boolean low = reading.fraction() * 100f < threshold(type);

			if (low && lowVitals.add(type) && config.alertSound() && isShown(type))
			{
				client.playSoundEffect(SoundEffectID.UI_BOOP);
			}
			else if (!low)
			{
				lowVitals.remove(type);
			}
		}
	}

	private boolean isShown(VitalType type)
	{
		switch (type)
		{
			case RUN:
				return config.runEnabled();
			case SPECIAL:
				return config.specialEnabled();
			default:
				return true;
		}
	}

	private int threshold(VitalType type)
	{
		switch (type)
		{
			case HITPOINTS:
				return config.hitpointsThreshold();
			case PRAYER:
				return config.prayerThreshold();
			case RUN:
				return config.runThreshold();
			default:
				return config.specialThreshold();
		}
	}

	/**
	 * Reads the two things worn equipment tells us: whether a holy wrench is on,
	 * and what the weapon's special attack costs.
	 */
	private void updateEquipment()
	{
		holyWrench = false;
		specialCost = 0;

		ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		if (equipment == null)
		{
			return;
		}

		Item weapon = equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
		if (weapon != null && weapon.getId() > 0)
		{
			specialCost = SpecialAttacks.cost(
				itemManager.getItemComposition(weapon.getId()).getName());
		}

		for (Item item : equipment.getItems())
		{
			if (item.getId() <= 0)
			{
				continue;
			}

			String name = itemManager.getItemComposition(item.getId()).getName().toLowerCase();

			for (String candidate : HOLY_WRENCH_ITEMS)
			{
				if (name.contains(candidate))
				{
					holyWrench = true;
					return;
				}
			}
		}
	}

	/**
	 * Reads what is under the cursor from the menu the client has already built,
	 * so nothing has to be scanned or guessed about the inventory.
	 */
	private void updatePreview()
	{
		previewType = null;
		previewAmount = 0;

		if (!config.healPreview())
		{
			return;
		}

		MenuEntry[] entries = client.getMenu().getMenuEntries();
		if (entries.length == 0)
		{
			return;
		}

		// The last entry is the one a left click would take.
		MenuEntry top = entries[entries.length - 1];
		int itemId = top.getItemId();
		if (itemId <= 0 || !isConsumeOption(top.getOption()))
		{
			return;
		}

		ItemComposition composition = itemManager.getItemComposition(itemId);
		RestoreValues.Restore restore = RestoreValues.forItem(composition.getName());
		if (restore == null)
		{
			return;
		}

		Reading reading = readings.get(restore.type);
		if (reading == null)
		{
			return;
		}

		previewType = restore.type;
		previewAmount = restore.amount(reading.max, holyWrench);

		// Anything that cannot overheal is capped, so the preview never promises
		// more than the segment can actually gain.
		if (!restore.overheals)
		{
			previewAmount = Math.min(previewAmount, Math.max(0, reading.max - reading.current));
		}
	}

	private static boolean isConsumeOption(String option)
	{
		if (option == null)
		{
			return false;
		}

		String lower = option.toLowerCase();
		return lower.equals("eat") || lower.equals("drink") || lower.equals("guzzle");
	}

	// ------------------------------------------------------------ Overlay reads

	Reading reading(VitalType type)
	{
		return readings.get(type);
	}

	MeterState meterState(VitalType type)
	{
		return meters.get(type);
	}

	List<StatBoost> getBoosts()
	{
		return boosts;
	}

	List<Prayer> getActivePrayers()
	{
		return activePrayers;
	}

	/**
	 * Whether you count as in combat, which drives the opacity. Kept separate
	 * from the hide delay so that changing when the brackets disappear does not
	 * also change when they brighten.
	 */
	boolean inCombat()
	{
		return System.currentTimeMillis() - lastCombatMillis <= config.combatTimeout() * 1000L;
	}

	boolean pastHideDelay()
	{
		return System.currentTimeMillis() - lastCombatMillis > config.hideDelay() * 1000L;
	}

	/**
	 * Strength of the damage flash, 1 the moment a hit lands and fading to 0.
	 */
	float hitFlash()
	{
		return config.hitFlash() ? damageFade() : 0f;
	}

	/**
	 * How recently a hit landed, 1 the moment it does and fading to 0.
	 *
	 * <p>Kept separate from the flash so that anything else keying off a hit is
	 * not switched off by the bracket's own flash setting.
	 */
	float damageFade()
	{
		long age = System.currentTimeMillis() - lastDamageMillis;
		if (age < 0 || age > FLASH_MILLIS)
		{
			return 0f;
		}

		return 1f - age / (float) FLASH_MILLIS;
	}

	/**
	 * A vital's current value alongside both its maximum and its real maximum.
	 * The two differ only while overhealed.
	 */
	static final class Reading
	{
		final int current;
		final int max;
		final int realMax;

		Reading(int current, int max, int realMax)
		{
			this.current = current;
			this.max = max;
			this.realMax = realMax;
		}

		/**
		 * The value the segment is scaled against, which grows to fit an overheal.
		 */
		int scale()
		{
			return Math.max(1, Math.max(current, realMax));
		}

		float fraction()
		{
			return current / (float) scale();
		}

		boolean isOverhealed()
		{
			return current > realMax;
		}
	}

	@Provides
	VitalsHudConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(VitalsHudConfig.class);
	}
}

package com.vitalshud;

import java.awt.Shape;
import java.awt.geom.PathIterator;
import java.awt.geom.Rectangle2D;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class OutlineRendererTest
{
	private static final Rectangle2D FRAME = new Rectangle2D.Double(0, 0, 100, 200);
	private static final double TOLERANCE = 0.5d;

	@Test
	public void subPathTakesTheRequestedShareOfTheLength()
	{
		Shape bracket = OutlineRenderer.bracket(FRAME, BracketSide.LEFT, 20d, 0d);
		double full = length(bracket);

		assertEquals(full / 2d, length(OutlineRenderer.subPath(bracket, 0d, 0.5d)), TOLERANCE);
		assertEquals(full / 4d, length(OutlineRenderer.subPath(bracket, 0d, 0.25d)), TOLERANCE);
		assertEquals(full, length(OutlineRenderer.subPath(bracket, 0d, 1d)), TOLERANCE);
	}

	@Test
	public void subPathHandlesAMiddleStretch()
	{
		Shape bracket = OutlineRenderer.bracket(FRAME, BracketSide.RIGHT, 20d, 0d);
		double full = length(bracket);

		assertEquals(full / 2d, length(OutlineRenderer.subPath(bracket, 0.25d, 0.75d)), TOLERANCE);
	}

	@Test
	public void subPathIgnoresTheOrderOfItsBounds()
	{
		Shape bracket = OutlineRenderer.bracket(FRAME, BracketSide.BOTTOM, 20d, 0d);

		assertEquals(
			length(OutlineRenderer.subPath(bracket, 0.2d, 0.8d)),
			length(OutlineRenderer.subPath(bracket, 0.8d, 0.2d)),
			TOLERANCE);
	}

	@Test
	public void anEmptyStretchGivesNothingToDraw()
	{
		Shape bracket = OutlineRenderer.bracket(FRAME, BracketSide.TOP, 20d, 0d);

		assertNull(OutlineRenderer.subPath(bracket, 0.5d, 0.5d));
		assertNull(OutlineRenderer.subPath(bracket, 0d, 0d));
	}

	@Test
	public void bracketsAreTheSameLengthWhicheverSideTheyTake()
	{
		Rectangle2D square = new Rectangle2D.Double(0, 0, 100, 100);

		double left = length(OutlineRenderer.bracket(square, BracketSide.LEFT, 20d, 0d));
		double right = length(OutlineRenderer.bracket(square, BracketSide.RIGHT, 20d, 0d));
		double bottom = length(OutlineRenderer.bracket(square, BracketSide.BOTTOM, 20d, 0d));

		assertEquals(left, right, TOLERANCE);
		assertEquals(left, bottom, TOLERANCE);
	}

	@Test
	public void aRoundedBracketStillSpansItsSide()
	{
		Shape square = OutlineRenderer.bracket(FRAME, BracketSide.LEFT, 20d, 0d);
		Shape rounded = OutlineRenderer.bracket(FRAME, BracketSide.LEFT, 20d, 8d);

		assertNotNull(rounded);

		// Rounding cuts the corners, so the path can only get shorter - but not by
		// so much that the bracket stops reaching along its side.
		assertTrue(length(rounded) < length(square));
		assertTrue(length(rounded) > length(square) * 0.8d);
	}

	private static double length(Shape path)
	{
		double[] coords = new double[6];
		double total = 0d;
		double previousX = 0d;
		double previousY = 0d;

		for (PathIterator it = path.getPathIterator(null, 0.1d); !it.isDone(); it.next())
		{
			int type = it.currentSegment(coords);

			if (type == PathIterator.SEG_LINETO)
			{
				total += Math.hypot(coords[0] - previousX, coords[1] - previousY);
			}

			previousX = coords[0];
			previousY = coords[1];
		}

		return total;
	}
}

package com.vitalshud;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class RestoreValuesTest
{
	@Test
	public void normaliseStripsDoseAndCase()
	{
		assertEquals("prayer potion", RestoreValues.normalise("Prayer potion(4)"));
		assertEquals("prayer potion", RestoreValues.normalise("PRAYER POTION(1)"));
		assertEquals("shark", RestoreValues.normalise("  Shark  "));
	}

	@Test
	public void normaliseStripsBlightedPrefix()
	{
		assertEquals("super restore", RestoreValues.normalise("Blighted super restore(4)"));
		assertEquals("manta ray", RestoreValues.normalise("Blighted manta ray"));
	}

	@Test
	public void everyDoseResolvesToOneEntry()
	{
		RestoreValues.Restore one = RestoreValues.forItem("Super restore(1)");
		RestoreValues.Restore four = RestoreValues.forItem("Super restore(4)");

		assertNotNull(one);
		assertEquals(one, four);
	}

	@Test
	public void foodRestoresAFlatAmount()
	{
		RestoreValues.Restore shark = RestoreValues.forItem("Shark");

		assertNotNull(shark);
		assertEquals(VitalType.HITPOINTS, shark.type);

		// Food does not scale, so the level it is handed makes no difference.
		assertEquals(20, shark.amount(99, false));
		assertEquals(20, shark.amount(10, false));
	}

	@Test
	public void prayerPotionScalesWithLevel()
	{
		RestoreValues.Restore potion = RestoreValues.forItem("Prayer potion(4)");

		assertNotNull(potion);
		assertEquals(VitalType.PRAYER, potion.type);
		assertEquals(7 + 24, potion.amount(99, false));
		assertEquals(7 + 10, potion.amount(43, false));
	}

	@Test
	public void holyWrenchOnlyHelpsPrayerPotions()
	{
		RestoreValues.Restore potion = RestoreValues.forItem("Prayer potion(4)");
		RestoreValues.Restore brew = RestoreValues.forItem("Ancient brew(4)");
		RestoreValues.Restore shark = RestoreValues.forItem("Shark");

		assertNotNull(potion);
		assertNotNull(brew);
		assertNotNull(shark);

		assertTrue(potion.amount(99, true) > potion.amount(99, false));
		assertEquals(brew.amount(99, false), brew.amount(99, true));
		assertEquals(shark.amount(99, false), shark.amount(99, true));
	}

	@Test
	public void brewsMayExceedTheMaximum()
	{
		RestoreValues.Restore brew = RestoreValues.forItem("Saradomin brew(4)");

		assertNotNull(brew);
		assertTrue(brew.overheals);
		assertEquals(2 + 14, brew.amount(99, false));
	}

	@Test
	public void unknownItemsHaveNoRestore()
	{
		assertNull(RestoreValues.forItem("Dragon scimitar"));
		assertNull(RestoreValues.forItem(null));
	}
}

package com.vitalshud;

