package com.vitalshud;

import java.awt.Color;
import java.awt.Polygon;
import java.awt.geom.Point2D;
import java.awt.geom.Rectangle2D;
import java.awt.image.BufferedImage;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The arithmetic behind where the brackets and their icons land. None of it
 * needs a client, and all of it has been got wrong at least once.
 */
public class VitalsHudGeometryTest
{
	private static final double EPSILON = 1e-9d;

	// ------------------------------------------------------------ bracketFrame

	@Test
	public void firstBracketOnASideSitsOnTheFrameItself()
	{
		Rectangle2D frame = new Rectangle2D.Double(10d, 20d, 100d, 200d);

		assertSame(frame, VitalsHudOverlay.bracketFrame(frame, BracketSide.LEFT, 5d, 0));
	}

	@Test
	public void stackedBracketsArePushedOutwardsNotInwards()
	{
		Rectangle2D frame = new Rectangle2D.Double(10d, 20d, 100d, 200d);

		Rectangle2D left = VitalsHudOverlay.bracketFrame(frame, BracketSide.LEFT, 5d, 1);
		Rectangle2D right = VitalsHudOverlay.bracketFrame(frame, BracketSide.RIGHT, 5d, 1);

		// Left grows to the left, right grows to the right; neither moves the edge
		// the other one sits on.
		assertEquals(0d, left.getX(), EPSILON);
		assertEquals(110d, left.getMaxX(), EPSILON);

		assertEquals(10d, right.getX(), EPSILON);
		assertEquals(120d, right.getMaxX(), EPSILON);
	}

	@Test
	public void stackingIsSymmetricTopToBottom()
	{
		Rectangle2D frame = new Rectangle2D.Double(10d, 20d, 100d, 200d);

		Rectangle2D top = VitalsHudOverlay.bracketFrame(frame, BracketSide.TOP, 4d, 2);
		Rectangle2D bottom = VitalsHudOverlay.bracketFrame(frame, BracketSide.BOTTOM, 4d, 2);

		assertEquals(frame.getMinY() - top.getMinY(), bottom.getMaxY() - frame.getMaxY(), EPSILON);
		assertEquals(top.getHeight(), bottom.getHeight(), EPSILON);
	}

	@Test
	public void aFrameCannotBePushedDownToNothing()
	{
		Rectangle2D frame = new Rectangle2D.Double(0d, 0d, 100d, 200d);

		Rectangle2D pushed = VitalsHudOverlay.bracketFrame(frame, BracketSide.LEFT, -500d, 1);

		assertTrue(pushed.getWidth() >= 1d);
		assertTrue(pushed.getHeight() >= 1d);
	}

	// --------------------------------------------------------------- fillRange

	@Test
	public void aBracketClearingNothingFillsEndToEnd()
	{
		assertRange(0f, 1f, VitalsHudOverlay.fillRange(100d, 0d, 0d));
	}

	@Test
	public void clearedCornersHoldTheFillOffBothEnds()
	{
		assertRange(0.1f, 0.8f, VitalsHudOverlay.fillRange(100d, 10d, 20d));
	}

	@Test
	public void aBracketWithNoLengthFillsEndToEndRatherThanDividingByZero()
	{
		assertRange(0f, 1f, VitalsHudOverlay.fillRange(0d, 10d, 10d));
		assertRange(0f, 1f, VitalsHudOverlay.fillRange(-5d, 10d, 10d));
	}

	@Test
	public void neighboursReachingRightAcrossStillLeaveTheMiddleTenth()
	{
		// Both returns claim the whole bracket. Without the clamps this inverts,
		// and the fill is drawn backwards or not at all.
		float[] range = VitalsHudOverlay.fillRange(100d, 500d, 500d);

		assertRange(0.45f, 0.55f, range);
		assertTrue("the fill must not invert", range[1] > range[0]);
	}

	@Test
	public void aRangeIsNeverInvertedForAnyClearance()
	{
		for (double lo = 0d; lo <= 200d; lo += 7d)
		{
			for (double hi = 0d; hi <= 200d; hi += 7d)
			{
				float[] range = VitalsHudOverlay.fillRange(100d, lo, hi);

				assertTrue("inverted at lo=" + lo + " hi=" + hi, range[1] > range[0]);
				assertTrue(range[0] >= 0f);
				assertTrue(range[1] <= 1f);
			}
		}
	}

	@Test
	public void theWholeBracketRangeCannotBeEditedByItsCaller()
	{
		float[] first = VitalsHudOverlay.fillRange(0d, 0d, 0d);
		first[0] = 0.5f;

		assertRange(0f, 1f, VitalsHudOverlay.fillRange(0d, 0d, 0d));
	}

	// --------------------------------------------------------------- artCentre

	@Test
	public void artworkFillingItsImageCentresOnTheMiddle()
	{
		Point2D.Double centre = VitalsHudOverlay.measureArtCentre(filled(10, 10, 0, 0, 10, 10));

		assertEquals(0.5d, centre.x, EPSILON);
		assertEquals(0.5d, centre.y, EPSILON);
	}

	@Test
	public void unevenPaddingMovesTheCentreOffTheImagesMiddle()
	{
		// Artwork in the left half only: its centre is a quarter of the way across,
		// not half. This is the heart's problem, which centring on the image box
		// got wrong.
		Point2D.Double centre = VitalsHudOverlay.measureArtCentre(filled(20, 20, 0, 0, 10, 20));

		assertEquals(0.25d, centre.x, EPSILON);
		assertEquals(0.5d, centre.y, EPSILON);
	}

	@Test
	public void aBlankSpriteFallsBackToItsOwnMiddle()
	{
		Point2D.Double centre = VitalsHudOverlay.measureArtCentre(
			new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB));

		assertEquals(0.5d, centre.x, EPSILON);
		assertEquals(0.5d, centre.y, EPSILON);
	}

	@Test
	public void nearlyTransparentPixelsCountAsPaddingRatherThanArtwork()
	{
		BufferedImage icon = filled(20, 20, 0, 0, 10, 20);

		// A faint wash over the right half must not drag the centre back.
		for (int y = 0; y < 20; y++)
		{
			for (int x = 10; x < 20; x++)
			{
				icon.setRGB(x, y, 0x08ffffff);
			}
		}

		assertEquals(0.25d, VitalsHudOverlay.measureArtCentre(icon).x, EPSILON);
	}

	// --------------------------------------------------------------- measuring

	@Test
	public void aTilePolygonMeasuresItsOwnSideAgainstATilesWidth()
	{
		// A tile drawn as a 128px square is exactly one pixel per world unit.
		Polygon tile = new Polygon(
			new int[]{0, 128, 128, 0},
			new int[]{0, 0, 128, 128}, 4);

		assertEquals(1d, CharacterMeasure.measureTile(tile), EPSILON);
	}

	@Test
	public void aMissingOrDegenerateTileMeasuresNothing()
	{
		assertEquals(0d, CharacterMeasure.measureTile(null), EPSILON);
		assertEquals(0d, CharacterMeasure.measureTile(new Polygon()), EPSILON);
	}

	@Test
	public void theBoxStandsOnTheFeetAndIsCentredOnThem()
	{
		Rectangle2D box = CharacterMeasure.box(100d, 300d, 1d, 1d);

		assertEquals(100d, box.getCenterX(), EPSILON);
		assertEquals("the box stands on the feet", 300d, box.getMaxY(), EPSILON);
		assertEquals(CharacterMeasure.PLAYER_HEIGHT, box.getHeight(), EPSILON);
	}

	@Test
	public void cameraSquashShortensTheBoxWithoutNarrowingIt()
	{
		Rectangle2D upright = CharacterMeasure.box(0d, 0d, 1d, 1d);
		Rectangle2D squashed = CharacterMeasure.box(0d, 0d, 1d, 0.5d);

		assertEquals(upright.getWidth(), squashed.getWidth(), EPSILON);
		assertEquals(upright.getHeight() / 2d, squashed.getHeight(), EPSILON);
	}

	@Test
	public void zoomScalesTheBoxInBothDirections()
	{
		Rectangle2D near = CharacterMeasure.box(0d, 0d, 2d, 1d);
		Rectangle2D far = CharacterMeasure.box(0d, 0d, 1d, 1d);

		assertEquals(far.getWidth() * 2d, near.getWidth(), EPSILON);
		assertEquals(far.getHeight() * 2d, near.getHeight(), EPSILON);
	}

	@Test
	public void nonsenseSquashReadingsAreRejected()
	{
		assertTrue(CharacterMeasure.usableSquash(1d));
		assertTrue(CharacterMeasure.usableSquash(0.4d));

		// A projection that came back backwards, flat, or taller than the world.
		assertTrue(!CharacterMeasure.usableSquash(0d));
		assertTrue(!CharacterMeasure.usableSquash(-1d));
		assertTrue(!CharacterMeasure.usableSquash(5d));
	}

	// ----------------------------------------------------------------- helpers

	private static void assertRange(float start, float end, float[] actual)
	{
		assertEquals("start", start, actual[0], 1e-6f);
		assertEquals("end", end, actual[1], 1e-6f);
	}

	/**
	 * An image whose artwork occupies exactly the given rectangle.
	 */
	private static BufferedImage filled(int width, int height, int x, int y, int w, int h)
	{
		BufferedImage icon = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);

		for (int py = y; py < y + h; py++)
		{
			for (int px = x; px < x + w; px++)
			{
				icon.setRGB(px, py, Color.WHITE.getRGB());
			}
		}

		return icon;
	}
}

